            _mapper_need_v1(self.counters['attempts'] < limits['attempts'] and self.by_path.get(name, 0) < row['attempt_limit'], 'BASIS_ATTEMPTS_EXHAUSTED')
            self.counters['attempts'] += 1; self.by_path[name] = self.by_path.get(name, 0) + 1
