def _ordinary_rp5a_bootstrap_header_v1(environment, *, repo_root, phase, deadline_ns):
 keys = {key.upper() for key in environment}
 selected = keys.intersection(_SCAN_TRANSPORT_KEYS)
 if not selected:
  return None
 if selected != set(_SCAN_TRANSPORT_KEYS):
  raise ValueError('ORDINARY_R_COMPLETE_ORIGINAL_BOOTSTRAP_CONTROLS')
 values = {}
 for key in _SCAN_TRANSPORT_KEYS:
  value = environment.get(key)
  if type(value) is not str or not value:
   raise ValueError('ORDINARY_R_ORIGINAL_BOOTSTRAP_CONTROL_TYPE')
  if key == 'QTT_SCAN_PHASE':
   values[key] = value
  else:
   if re.fullmatch(r'[1-9][0-9]*', value) is None:
    raise ValueError('ORDINARY_R_CANONICAL_ORIGINAL_BOOTSTRAP_INTEGER')
   values[key] = int(value)
 limits = _ScanRunReadLimits(*(values[key] for key in (
  'QTT_SCAN_BYTE_LIMIT', 'QTT_SCAN_NODE_LIMIT', 'QTT_SCAN_DEPTH_LIMIT', 'QTT_SCAN_PROFILE_LIMIT')))
 if limits.byte_limit > 32 << 20 or values['QTT_SCAN_PHASE'] != phase:
  raise ValueError('ORDINARY_R_SOURCE_BOUND_BOOTSTRAP_HEADER_LIMIT')
 process_root = Path(_linux_preflight_path_v1(environment[PROCESS_ROOT_ENV]))
 attestation = attest_inherited_validation_run(Path(repo_root),
  inherited_run_id=environment[RUN_ID_ENV],
  inherited_evidence_root=Path(_linux_preflight_path_v1(environment[EVIDENCE_ROOT_ENV])),
  explicit_basetemp=process_root / PYTEST_BASETEMP_DIR_NAME,
  scan_read_limits=limits, scan_deadline_ns=deadline_ns)
 value = _mapper_strip_run_extension_v1(attestation._scan_snapshot.value)
 if (set(value) != {'schema_version', 'run_id', 'phase', 'command_count',
   'text_integrity_preflight_state', 'paths', 'filesystem_probe', 'rp5a_occurrence_programmes'}
   or type(value['schema_version']) is not int or value['schema_version'] != SCHEMA_VERSION
   or value['run_id'] != attestation.run_id or value['phase'] != phase
   or type(value['command_count']) is not int or value['command_count'] != values['QTT_SCAN_COMMAND_COUNT']
   or attestation.process_root != process_root):
  raise ValueError('ORDINARY_R_ORIGINAL_INHERITED_BOOTSTRAP_HEADER')
 table = _ordinary_rp5a_table_projection_v1(value['rp5a_occurrence_programmes'],
  run_id=attestation.run_id, phase=phase, command_count=value['command_count'],
  repo_root=Path(repo_root), _json_arrays_v1=True)
 index = values['QTT_SCAN_COMMAND_INDEX']
 row = table[str(index)]
 if (type(row['argv']) is not tuple or _rp5a_consumer_role_v1(row['argv'], Path(repo_root)) != row['role']
   or limits != _ScanRunReadLimits(**row['read_limits'])
   or values['QTT_SCAN_DEADLINE_NS'] != row['deadline_ns']):
  raise ValueError('ORDINARY_R_ORIGINAL_PLANNED_ARGV_BEFORE_BINDING_READ')
 return attestation, row, index


