            self.observations.append(dict(kind='command',argv=argv,receipt=_json_compatible(receipt)))
            terminal_parent = (ordinary_selected and getattr(ordinary, '_ordinary_parent_git_record_v1', None) is not None
                and ordinary._ordinary_query_parent_git_terminal_v1(record, receipt))
            if ordinary_selected: ordinary._ordinary_query_returned_v1(self, argv)
