def _ordinary_nested_source_limits_v1(scope, paths, plan, execution_plan, effects, resource,
     *, entry_limit, snapshot_byte_limit, read_byte_limit):
    """Issue the original gate's finite limits once before C, from actual operands.

    This product does not supply a missing native/callee programme. Every row
    must already have its same source-selected checked native programme.
    """
    _preflight_require_v1(type(scope) is _LinuxPreflightScopeV1
     and effects is scope._ordinary_effect_programme_record_v1()
     and resource is scope._ordinary_resource_programme_v1
     and paths is scope._ordinary_bound_paths_v1 and plan is scope._ordinary_bound_plan_v1
     and execution_plan is scope._ordinary_execution_plan_v1
     and scope._ordinary_candidate_v1 is None
     and not hasattr(scope, '_ordinary_nested_limit_product_v1'),
     'ORDINARY_NESTED_ONE_SOURCE_ALLOCATION_BEFORE_C')
    selection = scope._ordinary_source_selection_v1
    positive = tuple((entry, scope._ordinary_nested_selection_v1(entry)) for entry in plan)
    positive = tuple((entry, selected) for entry, selected in positive if selected is not None)
    if not positive: return {}
    allocations = _ordinary_phase_allocation_rows_v1(scope, resource)
    _preflight_require_v1(type(allocations) is tuple and len(allocations) == len(plan)
     and all(type(value) is int and value > 0 for value in
      (entry_limit, snapshot_byte_limit, read_byte_limit)),
     'ORDINARY_NESTED_ORIGINAL_PHASE_ALLOCATIONS_AND_C_TOTALS')
    demand = resource['nested_evidence_programme']
    _preflight_require_v1(type(demand) is tuple and len(demand) == 18
     and demand == scope._ordinary_runner_owner_v1._ordinary_nested_resource_demand_v1(
      resource['ceiling_programme']) and len(positive) <= demand[1]
     and all(selected[0]['source_position'] in resource['ceiling_programme']['phase_source']['nested_positions']
      for entry, selected in positive), 'ORDINARY_NESTED_SOURCE_SELECTED_RESERVED_ROWS')
    evidence = resource['ceiling_programme']['evidence_programme']
    count = len(plan)
    root = scope._ordinary_run_evidence_root_v1
    fd = root['slot']['returned_fd']
    before = scope._ordinary_factory_call_v1(os.fstat, fd)
    listing = scope._ordinary_factory_iterator_v1(fd)
    baseline, errors = {}, []
    try:
     while True:
      try: item = scope._ordinary_factory_call_v1(next, listing['iterator'])
      except StopIteration: break
      _preflight_require_v1(len(baseline) < entry_limit and type(item.name) is str
       and item.name not in ('', '.', '..') and '/' not in item.name and '\\' not in item.name
       and item.name.casefold() not in {name.casefold() for name in baseline},
       'ORDINARY_NESTED_BOUNDED_ORIGINAL_INPUT_ROSTER')
      info = scope._ordinary_factory_call_v1(os.stat, item.name, dir_fd=fd, follow_symlinks=False)
      _preflight_require_v1(not _stat_is_reparse_point(info)
       and (stat.S_ISDIR(info.st_mode) or stat.S_ISREG(info.st_mode) and info.st_nlink == 1),
       'ORDINARY_NESTED_ORIGINAL_INPUT_KIND')
      baseline[item.name] = _NestedPytestEvidenceV1._entry_version(info)
    except BaseException as error: errors.append(error)
    scope._ordinary_factory_iterator_close_v1(listing, errors)
    _scan_raise_errors(errors)
    after = scope._ordinary_factory_call_v1(os.fstat, fd)
    _preflight_require_v1(_NestedPytestEvidenceV1._entry_version(before)
     == _NestedPytestEvidenceV1._entry_version(after)
     and (after.st_dev, after.st_ino) == root['identity'] and len(baseline) <= demand[2]
     and not any(re.fullmatch(r'nested-pytest-[1-9][0-9]*-(0|[1-9][0-9]*)', name, re.ASCII)
      for name in baseline),
     'ORDINARY_NESTED_COMPLETE_STABLE_INPUT_ROSTER')
    origin, app_end, custody_end, final_end = resource['original_cutoffs']
    child_end = origin + 3 * (app_end - origin) // 4
    _preflight_require_v1(time.monotonic_ns() < child_end < app_end < custody_end < final_end,
     'ORDINARY_NESTED_ORIGINAL_FIXED_DEADLINE_INTERSECTION')
    header_cap = evidence['binding_payload_bytes']
    receipt_cap = evidence['atomic_payload_bytes']
    _preflight_require_v1(header_cap == receipt_cap == 1048576,
     'ORDINARY_NESTED_ORIGINAL_HEADER_AND_RECEIPT_CAPS')
    rounds = count + 6
    wrapper_count = len(positive)
    entries = len(baseline) + 3 * count + wrapper_count + 4
    limits, rows = {}, []
    for entry, selected in positive:
     allocation = allocations[entry.command_index - 1]
     _preflight_require_v1(selected is not None and allocation['native_programme']
      is selected[0]['native_programme'], 'ORDINARY_NESTED_SAME_SOURCE_NATIVE_ALLOCATION')
     output = allocation['stdout_bytes'] + allocation['stderr_bytes']
     _preflight_require_v1(max(allocation['stdout_bytes'], allocation['stderr_bytes'])
      <= resource['ceiling_programme']['output_partition']['application_stream_bytes'],
      'ORDINARY_NESTED_OUTPUT_OPERANDS_WITHIN_ORIGINAL_SOURCE_ALLOCATION')
     file_cap = max(allocation['stdout_bytes'], allocation['stderr_bytes'], receipt_cap, header_cap)
     _preflight_require_v1(file_cap <= 128 << 20, 'ORDINARY_NESTED_ORIGINAL_NATIVE_FILE_CAP')
     one = output + receipt_cap
     values = dict(entry_limit=entries, file_byte_limit=file_cap,
      read_byte_limit=(5 + 3 * rounds) * one + (3 + rounds) * header_cap + 32,
      retained_byte_limit=4 * one + 3 * header_cap + 2 * file_cap,
      deadline_ns=custody_end, execution_deadline_ns=app_end,
      child_execution_deadline_ns=child_end)
     if _mapper_nested_pytest_args_v1(entry.argv, Path(entry.cwd)) is None:
      del values['child_execution_deadline_ns']
     limits[entry.command_index] = values
     rows.append((entry, allocation, selected, tuple(values.items())))
    retained = sum(value['retained_byte_limit'] for value in limits.values())
    reads = sum(value['read_byte_limit'] for value in limits.values())
    names = sum(value['entry_limit'] for value in limits.values())
    _preflight_require_v1(retained < snapshot_byte_limit and reads < read_byte_limit
     and names < entry_limit and retained < resource['limits']['heap_byte_limit']
     and retained <= demand[8] and reads <= demand[6] and entries <= demand[3],
     'ORDINARY_NESTED_SHARED_C_AND_HEAP_INTERSECTION_NO_QUOTA_INCREASE')
    record = dict(scope=scope, paths=paths, plan=plan, execution_plan=execution_plan,
     effects=effects, resource=resource, selection=selection, allocations=allocations,
     baseline=baseline, rows=tuple(rows), limits=limits, original_cutoffs=resource['original_cutoffs'],
     rounds=rounds, wrapper_count=wrapper_count, positive=positive,
     retained=retained, reads=reads, entries=names,
     owner=(os.getpid(), threading.get_ident()), errors=[])
    record['original'] = (record, scope, paths, plan, execution_plan, effects, resource,
     selection, allocations, baseline, tuple(baseline.items()), record['rows'], limits,
     tuple((key, value, tuple(value.items())) for key, value in limits.items()), record['owner'],
     positive, wrapper_count, demand)
    scope._ordinary_nested_limit_product_v1 = scope._ordinary_original_nested_limit_product_v1 = record
    return limits


