def _ordinary_bind_run_scratch_roots_v1(scope, paths):
 """Pin stable custody parents; pytest's exact p child is disposable."""
 runner = scope._ordinary_runner_owner_v1
 _preflight_require_v1(type(scope) is _LinuxPreflightScopeV1
  and runner is scope._ordinary_original_runner_owner_v1
  and type(paths) is runner.ValidationRunPathsV1
  and paths is scope._ordinary_bound_paths_v1
  and not hasattr(scope, '_ordinary_run_scratch_roots_v1'),
  'ORDINARY_SCRATCH_ORIGINAL_RESOLVER_SINGLE_BINDING')
 image = scope._ordinary_host_output_image_v1
 selected = (paths.validation_output_root, paths.pytest_basetemp_root)
 _preflight_require_v1(selected[0] != selected[1]
  and not selected[0].is_relative_to(selected[1])
  and not selected[1].is_relative_to(selected[0])
  and all(path.is_relative_to(paths.process_root) and path != paths.process_root
   and path.is_relative_to(image['mount_path']) for path in selected)
  and paths.process_root.is_relative_to(image['mount_path'])
  and paths.process_root != image['mount_path']
  and selected[1] == paths.process_root / PYTEST_BASETEMP_DIR_NAME
  and image['mounted'] and not image['disposed'],
  'ORDINARY_SCRATCH_EXACT_DISJOINT_OWNED_HOST_IMAGE_ROLES')
 disposable = dict(path=selected[1], parent=paths.process_root,
  name=PYTEST_BASETEMP_DIR_NAME, kind='DIRECTORY')
 record = dict(scope=scope, paths=paths, image=image, roots=selected, operands=[],
  disposable=disposable, errors=[])
 record['disposable_original'] = tuple(disposable.items())
 record['original'] = (record, scope, paths, image, selected, record['operands'], record['errors'],
  (os.getpid(), threading.get_ident()), disposable, record['disposable_original'])
 scope._ordinary_run_scratch_roots_v1 = scope._ordinary_original_run_scratch_roots_v1 = record
 try:
  for path in (paths.process_root, selected[0]):
   chain = scope._ordinary_factory_chain_v1(path.parent)
   before = scope._ordinary_factory_call_v1(os.lstat, path)
   slot = scope._ordinary_factory_slot_v1(path, 'ORDINARY_SELECTED_RUN_SCRATCH_ROOT')
   operand = dict(path=path, slot=slot, chain=chain, identity=None, attributes=None)
   record['operands'].append(operand)
   fd = scope._ordinary_factory_open_v1(slot, path,
    os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
   handle = scope._ordinary_factory_call_v1(os.fstat, fd)
   after = scope._ordinary_factory_call_v1(os.lstat, path)
   _preflight_require_v1(stat.S_ISDIR(handle.st_mode) and not _stat_is_reparse_point(before)
    and _same_observed_file(before, handle) and _same_observed_file(after, handle)
    and handle.st_dev == image['filesystem']['root_identity'][0]
    and (handle.st_uid, handle.st_gid, stat.S_IMODE(handle.st_mode)) == (0, 0, 0o700)
    and scope._ordinary_factory_chain_v1(path.parent) == chain,
    'ORDINARY_SCRATCH_ORIGINAL_NOFOLLOW_PATH_HANDLE_AND_PARENT_CHAIN')
   operand['identity'] = (handle.st_dev, handle.st_ino)
   operand['attributes'] = (handle.st_uid, handle.st_gid, stat.S_IMODE(handle.st_mode))
  record['operand_originals'] = tuple((operand, tuple(operand.items()))
   for operand in record['operands'])
  return _ordinary_run_scratch_roots_check_v1(scope, record)
 except BaseException as error:
  if all(error is not prior for prior in record['errors']): record['errors'].append(error)
  if all(error is not prior for prior in scope._ordinary_factory_errors_v1):
   scope._ordinary_factory_errors_v1.append(error)
  raise


def _ordinary_run_disposable_basetemp_check_v1(scope, record, *, settling=False):
 disposable = record['disposable']
 parent = record['operands'][0]
 _preflight_require_v1(tuple(disposable.items()) == record['disposable_original']
  and disposable['parent'] == parent['path'] == record['paths'].process_root
  and disposable['path'] == disposable['parent'] / disposable['name']
  and disposable['name'] == PYTEST_BASETEMP_DIR_NAME and disposable['kind'] == 'DIRECTORY',
  'ORDINARY_SCRATCH_EXACT_DISPOSABLE_BASETEMP_CHILD')
 parent_fd = parent['slot']['returned_fd']
 try:
  before = scope._ordinary_factory_call_v1(os.stat, disposable['name'], dir_fd=parent_fd,
   follow_symlinks=False, settling=settling)
 except FileNotFoundError:
  return None
 slot, errors = None, []
 try:
  _preflight_require_v1(stat.S_ISDIR(before.st_mode) and not _stat_is_reparse_point(before)
   and stat.S_IMODE(before.st_mode) == 0o700
   and before.st_dev == record['image']['filesystem']['root_identity'][0]
   and (before.st_dev, before.st_ino) not in tuple(value['identity'] for value in record['operands']),
   'ORDINARY_SCRATCH_DISPOSABLE_BASETEMP_ORDINARY_NONALIAS_DIRECTORY')
  slot = scope._ordinary_factory_slot_v1(disposable['path'],
   'ORDINARY_DISPOSABLE_BASETEMP_OBSERVER', settling=settling)
  fd = scope._ordinary_factory_open_v1(slot, disposable['name'],
   os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC,
   parent_fd=parent_fd, settling=settling)
  handle = scope._ordinary_factory_call_v1(os.fstat, fd, settling=settling)
  after = scope._ordinary_factory_call_v1(os.stat, disposable['name'], dir_fd=parent_fd,
   follow_symlinks=False, settling=settling)
  _preflight_require_v1(stat.S_ISDIR(handle.st_mode) and not _stat_is_reparse_point(after)
   and _same_observed_file(before, handle) and _same_observed_file(after, handle)
   and (before.st_uid, before.st_gid, stat.S_IMODE(before.st_mode))
    == (handle.st_uid, handle.st_gid, stat.S_IMODE(handle.st_mode))
    == (after.st_uid, after.st_gid, stat.S_IMODE(after.st_mode)),
   'ORDINARY_SCRATCH_DISPOSABLE_BASETEMP_SAME_ACQUISITION')
 except BaseException as error: errors.append(error)
 if slot is not None and not _mapper_slot_settled_v1(slot):
  try: scope._ordinary_factory_close_v1(slot, settling=settling)
  except BaseException as error: errors.append(error)
 _scan_raise_errors(errors)
 return None


def _ordinary_run_scratch_roots_check_v1(scope, record, *, settling=False):
 """Check stable custody and disposable p; this grants no APP writable mount."""
 try:
  original = record['original']
  _preflight_require_v1(record is scope._ordinary_run_scratch_roots_v1
   is scope._ordinary_original_run_scratch_roots_v1 and type(original) is tuple
   and len(original) == 10 and original[0] is record and original[1] is scope
   and original[2] is record['paths'] is scope._ordinary_bound_paths_v1
   and original[3] is record['image'] is scope._ordinary_host_output_image_v1
   and original[4] is record['roots'] and original[5] is record['operands']
   and original[6] is record['errors'] and not record['errors']
   and original[7] == (os.getpid(), threading.get_ident())
   and original[8] is record['disposable'] and original[9] is record['disposable_original']
   and len(record['operands']) == len(record['operand_originals']) == 2
   and record['roots'] == (record['paths'].validation_output_root, record['paths'].pytest_basetemp_root)
   and tuple(value['path'] for value in record['operands'])
    == (record['paths'].process_root, record['paths'].validation_output_root),
   'ORDINARY_SCRATCH_SAME_RESOLVER_OPERANDS_AND_OWNER')
  cleanup = getattr(scope, '_ordinary_run_cleanup_v1', None)
  if cleanup is not None and cleanup['prepared']:
   scope._ordinary_run_cleanup_checked_v1(record['paths'])
   _preflight_require_v1(cleanup['scratch'] is record,
    'ORDINARY_SCRATCH_ORIGINAL_COMPLETED_CLEANUP_ASSOCIATION')
   return record
  for operand, saved in record['operand_originals']:
   _preflight_require_v1(any(operand is value for value in record['operands'])
    and tuple(operand.items()) == saved and not _mapper_slot_settled_v1(operand['slot']),
    'ORDINARY_SCRATCH_RETAINED_ORIGINAL_DESCRIPTOR_SLOT')
   fd = operand['slot']['returned_fd']
   before = scope._ordinary_factory_call_v1(os.lstat, operand['path'], settling=settling)
   handle = scope._ordinary_factory_call_v1(os.fstat, fd, settling=settling)
   after = scope._ordinary_factory_call_v1(os.lstat, operand['path'], settling=settling)
   _preflight_require_v1(stat.S_ISDIR(handle.st_mode) and not _stat_is_reparse_point(before)
    and (before.st_dev, before.st_ino) == (handle.st_dev, handle.st_ino)
     == (after.st_dev, after.st_ino) == operand['identity']
    and (before.st_uid, before.st_gid, stat.S_IMODE(before.st_mode))
     == (handle.st_uid, handle.st_gid, stat.S_IMODE(handle.st_mode))
     == (after.st_uid, after.st_gid, stat.S_IMODE(after.st_mode)) == operand['attributes'],
    'ORDINARY_SCRATCH_ORIGINAL_LIVE_PATH_HANDLE_AND_ATTRIBUTES')
   chain = scope._ordinary_factory_chain_v1(operand['path'].parent, settling=settling)
   _preflight_require_v1(len(chain) == len(operand['chain'])
    and all(actual[0] == retained[0] and actual[1][:3] == retained[1][:3]
     for actual, retained in zip(chain, operand['chain'], strict=True)),
    'ORDINARY_SCRATCH_ORIGINAL_SAFE_ANCESTRY_IDENTITY')
  _ordinary_run_disposable_basetemp_check_v1(scope, record, settling=settling)
  return record
 except BaseException as error:
  if all(error is not prior for prior in record['errors']): record['errors'].append(error)
  if all(error is not prior for prior in scope._ordinary_factory_errors_v1):
   scope._ordinary_factory_errors_v1.append(error)
  raise


