def _ordinary_control_compiled_module_v1(raw, filename, *, flags, optimize):
 import ast, types
 _ordinary_control_dictionary_keys_v1(ast.__dict__)
 _ordinary_control_dictionary_keys_v1(types.__dict__)
 if type(raw) is not bytes or type(filename) is not str or not filename or '\0' in filename:
  raise ValueError('CONTROL_WHOLE_SOURCE_OR_FILENAME')
 if type(flags) is not int or flags < 0 or type(optimize) is not int or optimize not in (0, 1, 2):
  raise ValueError('CONTROL_ORIGINAL_LOADER_COMPILE_POLICY')
 tree = compile(raw, filename, 'exec', flags=flags | ast.PyCF_ONLY_AST,
  dont_inherit=True, optimize=optimize)
 root = compile(raw, filename, 'exec', flags=flags, dont_inherit=True, optimize=optimize)
 if type(root) is not types.CodeType: raise ValueError('CONTROL_COMPILED_MODULE')
 codes, pending = [], [root]
 while pending:
  code = pending.pop(); codes.append(code)
  pending.extend(x for x in code.co_consts if type(x) is types.CodeType)
 from tools.validation_scope_registry import _ordinary_control_selected_source_unit_v1
 _, definitions = _ordinary_control_selected_source_unit_v1(tree, ())
 return root, tuple(codes), definitions


def _ordinary_control_compiled_selections_v1(raw, filename, *, flags, optimize, selected):
 import ast, types
 _ordinary_control_dictionary_keys_v1(ast.__dict__)
 _ordinary_control_dictionary_keys_v1(types.__dict__)
 if type(raw) is not bytes or type(filename) is not str or not filename or '\0' in filename:
  raise ValueError('CONTROL_WHOLE_SOURCE_OR_FILENAME')
 if type(flags) is not int or flags < 0 or type(optimize) is not int or optimize not in (0, 1, 2):
  raise ValueError('CONTROL_ORIGINAL_LOADER_COMPILE_POLICY')
 if type(selected) is not tuple:
  raise ValueError('CONTROL_SELECTED_SOURCE_DECLARATION_FIELDS')
 if not selected:
  return _ordinary_control_compiled_module_v1(raw, filename, flags=flags, optimize=optimize)
 return _ordinary_control_compiled_containers_v1(raw, filename,
  flags=flags, optimize=optimize, selected=selected)


