def _ordinary_controller_data_source_initialize_v1(scope, resource, inputs, *,
  _ordinary_source_stage_v1=None):
 import types
 _preflight_require_v1(type(scope) is _LinuxPreflightScopeV1
  and resource is scope._ordinary_resource_programme_v1
  is scope._ordinary_original_resource_programme_v1[0]
  and not hasattr(scope, '_ordinary_controller_data_initialization_v1')
  and not hasattr(scope, '_ordinary_controller_data_initialization_attempted_v1'),
  'CONTROL_ONE_ORIGINAL_DATA_INITIALIZATION')
 scope._ordinary_controller_data_initialization_attempted_v1 = True
 attempt = None
 heap_record = None
 stage = _ordinary_source_stage_v1
 fields = ('module_inputs', 'selectors', 'default_rows', 'site_rows', 'platform_targets',
  'native_binding_primitives', 'operation_rows', 'operation_sources',
  'operation_snapshots', 'interpreter_storage_request', 'runtime_roles',
  'control_source_rows', 'delegated_control_rows', 'existing_heap_demand',
  'existing_raw_retained_demand', 'work_deadline_ns', 'data_file_byte_limit')
 try:
  _ordinary_control_dictionary_keys_v1(inputs)
  _preflight_require_v1(type(inputs) is dict
   and inputs is scope._ordinary_control_source_inputs_v1
   and all(key in inputs for key in fields),
   'CONTROL_AUTHENTIC_UPSTREAM_SOURCE_INPUTS_UNISSUED')
  input_continuity = (inputs,) + tuple(inputs[key] for key in fields)
  def input_check():
   _ordinary_control_dictionary_keys_v1(inputs)
   _preflight_require_v1(inputs is scope._ordinary_control_source_inputs_v1
    and all(inputs[key] is input_continuity[index+1]
     for index,key in enumerate(fields)), 'CONTROL_SOURCE_INPUT_POINTERS_RETAINED')
  runtime = scope._ordinary_bootstrap_runtime_v1
  acquisition = runtime['acquisition']
  runner_old = acquisition['runner_owner_original']
  runner = runner_old[1]
  _preflight_require_v1(type(runner) is types.ModuleType
   and runner is sys.modules.get(runner_old[3])
   and runner.__dict__ is runner_old[2], 'CONTROL_ORIGINAL_RUN_OWNER')
  runner._ordinary_bootstrap_runtime_check_v1(scope)
  heap_record = runner._ordinary_bootstrap_heap_record_v1(acquisition['heap_record'])
  module_attempt = scope._ordinary_control_module_inputs_v1
  _preflight_require_v1(type(stage) is dict and heap_record['active'] is stage
   and stage['complete'] is False and stage['error'] is None
   and stage['row'][0] == 'BEFORE_COMPILE'
   and module_attempt is scope._ordinary_original_control_module_inputs_v1
   and module_attempt['original'] is scope._ordinary_control_module_inputs_original_v1
   and module_attempt['heap'] is heap_record and module_attempt['stage'] is stage
   and module_attempt['complete'] and not module_attempt['errors']
   and inputs['module_inputs'] is module_attempt['result']
   is module_attempt['result_original'][0],
   'CONTROL_SAME_COMPILER_MODULE_ACQUISITION')
  runner._ordinary_bootstrap_heap_source_row_v1(heap_record['native_product'],
   stage['row'], stage['original'][3])
  errors = []
  attempt = dict(scope=scope, resource=resource, inputs=inputs, programme=None,
   product=None, layout=None, transfer=None, allocator=None, complete=False,
   errors=errors, input_continuity=input_continuity, heap_stage=stage)
  scope._ordinary_controller_data_initialization_v1 = attempt
  scope._ordinary_original_controller_data_initialization_v1 = attempt
  input_check()
  programme = _ordinary_control_source_programme_bind_v1(scope,
   module_inputs=inputs['module_inputs'], selectors=inputs['selectors'],
   default_rows=inputs['default_rows'], site_rows=inputs['site_rows'],
   platform_targets=inputs['platform_targets'],
   native_binding_primitives=inputs['native_binding_primitives'],
   operation_rows=inputs['operation_rows'], operation_sources=inputs['operation_sources'],
   operation_snapshots=inputs['operation_snapshots'],
   interpreter_storage_request=inputs['interpreter_storage_request'])
  attempt['programme'] = programme
  input_check()
  product = _ordinary_control_source_product_v1(scope, programme)
  attempt['product'] = product
  runner._ordinary_bootstrap_heap_stage_complete_v1(heap_record, stage, product)
  attempt['heap_stage'] = None
  stage = None
  input_check()
  installation = scope._ordinary_installation_copy_v1
  _ordinary_control_installation_bind_v1(scope, installation, product,
   inputs['operation_rows'], inputs['interpreter_storage_request'])
  input_check()
  layout = scope._ordinary_source_data_runtime_layout_v1(resource,
   runtime_roles=inputs['runtime_roles'], control_source_rows=inputs['control_source_rows'],
   delegated_control_rows=inputs['delegated_control_rows'], source_product=product,
   operation_rows=inputs['operation_rows'],
   interpreter_storage_request=inputs['interpreter_storage_request'])
  attempt['layout'] = layout
  input_check()
  transfer = runner._ordinary_bootstrap_heap_transfer_v1(scope, resource, heap_record)
  attempt['transfer'] = transfer
  _preflight_require_v1(type(inputs['existing_heap_demand']) is int
   and inputs['existing_heap_demand'] >= 0,
   'CONTROL_ORIGINAL_EXISTING_HEAP_COMPONENT')
  input_check()
  allocator = scope._ordinary_source_data_allocator_register_v1(resource,
   existing_heap_demand=inputs['existing_heap_demand'] + transfer[6],
   existing_raw_retained_demand=inputs['existing_raw_retained_demand'], runtime_layout=layout,
   work_deadline_ns=inputs['work_deadline_ns'], data_file_byte_limit=inputs['data_file_byte_limit'])
  attempt['allocator'] = allocator
  _preflight_require_v1(all(inputs[key] is input_continuity[index+1]
   for index,key in enumerate(fields)), 'CONTROL_SOURCE_INPUT_POINTERS_RETAINED')
  attempt['complete'] = True
  return allocator
 except BaseException as error:
  escaping_errors = [error]
  if stage is not None and heap_record is not None:
   try:
    runner._ordinary_bootstrap_heap_stage_failed_v1(heap_record, stage, error)
   except BaseException as accounting_error:
    escaping_errors.append(accounting_error)
  for caught in tuple(escaping_errors):
   if attempt is not None:
    try:
     _preflight_require_v1(attempt['errors'] is errors,
      'CONTROL_ORIGINAL_INITIALIZATION_ERROR_LIST')
     if all(caught is not old for old in errors): errors.append(caught)
    except BaseException as recording_error:
     escaping_errors.append(recording_error)
   try:
    owner_errors = scope._ordinary_factory_errors_v1
    _preflight_require_v1(type(owner_errors) is list,
     'CONTROL_ORIGINAL_SCOPE_ERROR_LIST')
    if all(caught is not old for old in owner_errors): owner_errors.append(caught)
   except BaseException as recording_error:
    escaping_errors.append(recording_error)
  _scan_raise_errors(escaping_errors)
  raise


