def _ordinary_pytest_installation_source_v1(scope, record, suffix, *, source_byte_limit, source_node_limit):
 """Read an exact original copied installation operand through its held owner."""
 import ast
 installation = scope._ordinary_installation_record_v1(scope._ordinary_installation_copy_v1['install'])
 install = installation['install']
 _preflight_require_v1(record['scope'] is scope and record['source'] is scope.source
  and installation is scope._ordinary_original_installation_copy_v1
  and installation['complete'] and not installation['errors']
  and installation['completion_original'][0] is installation
  and installation['completion_original'][1] is installation['target_versions']
  and installation['completion_original'][3] is installation['files'] is install.files
  and type(suffix) is str and suffix and not suffix.startswith('/')
  and type(source_byte_limit) is int and source_byte_limit > 0
  and type(source_node_limit) is int and source_node_limit > 0,
  'ORDINARY_PYTEST_INSTALLATION_ORIGINAL_CAPTURE_AND_PAIRED_COPY')
 _mapper_portable_relative_v1(suffix)
 matches = tuple((row, target, version) for row, target, version in installation['target_versions']
  if row['kind'] == 'file' and Path(row['path']).relative_to(install.root).as_posix().endswith('/' + suffix))
 _preflight_require_v1(len(matches) == 1,
  'ORDINARY_PYTEST_INSTALLATION_ONE_SOURCE_SELECTED_OPERAND')
 row, target, captured_version = matches[0]
 version = tuple(captured_version)
 expected = install.files[row['path']]
 _preflight_require_v1(type(expected) is bytes and len(expected) == row['logical_bytes']
  and len(expected) <= source_byte_limit and target in installation['target_paths']
  and target == installation['destination'] / Path(row['path']).relative_to(install.root),
  'ORDINARY_PYTEST_INSTALLATION_ORIGINAL_BYTES_NOT_A_NEW_COPY_EXPECTATION')
 source_form = ('INSTALLATION_PYTHON' if suffix.endswith('.py') else 'INSTALLATION_DATA')
 _preflight_require_v1(source_form == 'INSTALLATION_PYTHON' or
  Path(suffix).name in ('METADATA', 'entry_points.txt')
  and any(part.endswith('.dist-info') for part in Path(suffix).parts),
  'ORDINARY_PYTEST_INSTALLATION_FIXED_SOURCE_OR_MANIFEST_INPUT')
 cache = record['installation_operand_cache']
 _preflight_require_v1(type(cache) is dict and cache is record['original_installation_operand_cache']
  and (suffix, source_form) not in cache,
  'ORDINARY_PYTEST_INSTALLATION_ONE_ORIGINAL_CAPTURE')
 capturer = _ordinary_pytest_installation_source_v1
 observed = dict(path=suffix, source_form=source_form, installation=installation,
  install=install, row=row, target=target, version=version, raw=expected,
  raw_bytes=0, nodes=None, text=None, attempted=True, complete=False, error=None,
  capturer=capturer, capturer_code=capturer.__code__, capture_owner=record)
 record['installation_source_operands'].append(observed)
 descriptor = None
 errors = []
 try:
  before = scope._ordinary_factory_call_v1(os.lstat, target)
  descriptor = scope._ordinary_installation_open_v1(install, target)
  handle = scope._ordinary_factory_call_v1(os.fstat, descriptor)
  _preflight_require_v1(tuple(_LinuxPreflightCensusV1._version(before))
   == tuple(_LinuxPreflightCensusV1._version(handle)) == version
   and stat.S_ISREG(handle.st_mode) and handle.st_nlink == 1
   and (handle.st_uid, handle.st_gid) == (0, 0)
   and stat.S_IMODE(handle.st_mode) in (0o444, 0o555),
   'ORDINARY_PYTEST_INSTALLATION_CURRENT_PATH_HANDLE_AND_VERSION')
  position = 0
  while position < len(expected):
   raw = scope._ordinary_factory_call_v1(os.read, descriptor, min(65536, len(expected) - position))
   _preflight_require_v1(type(raw) is bytes, 'ORDINARY_PYTEST_INSTALLATION_READ_TYPE')
   observed['raw_bytes'] += len(raw)
   scope._ordinary_factory_debit_v1('raw_read', len(raw))
   expected_chunk = expected[position:position + len(raw)]
   scope._ordinary_factory_debit_v1('raw_read', len(expected_chunk))
   _preflight_require_v1(raw and raw == expected_chunk,
    'ORDINARY_PYTEST_INSTALLATION_FULL_INDEPENDENT_BYTE_COMPARISON')
   position += len(raw)
  suffix_raw = scope._ordinary_factory_call_v1(os.read, descriptor, 1)
  _preflight_require_v1(type(suffix_raw) is bytes, 'ORDINARY_PYTEST_INSTALLATION_EOF_TYPE')
  observed['raw_bytes'] += len(suffix_raw)
  scope._ordinary_factory_debit_v1('raw_read', len(suffix_raw))
  _preflight_require_v1(suffix_raw == b'' and observed['raw_bytes'] == len(expected)
   and tuple(_LinuxPreflightCensusV1._version(scope._ordinary_factory_call_v1(os.fstat, descriptor))) == version
   and tuple(_LinuxPreflightCensusV1._version(scope._ordinary_factory_call_v1(os.lstat, target))) == version,
   'ORDINARY_PYTEST_INSTALLATION_COMPLETE_EOF_AND_AFTER_USE_VERSION')
 except BaseException as error:
  errors.append(error)
 finally:
  if descriptor is not None:
   try: scope._ordinary_installation_close_v1(install, descriptor)
   except BaseException as error: errors.append(error)
 if errors:
  observed['error'] = errors[0]
  for error in errors:
   if all(error is not prior for prior in record['errors']): record['errors'].append(error)
   if all(error is not prior for prior in installation['errors']): installation['errors'].append(error)
   if all(error is not prior for prior in scope._ordinary_factory_errors_v1):
    scope._ordinary_factory_errors_v1.append(error)
  _scan_raise_errors(errors)
 try:
  _preflight_require_v1(tuple(_LinuxPreflightCensusV1._version(
   scope._ordinary_factory_call_v1(os.lstat, target))) == version,
   'ORDINARY_PYTEST_INSTALLATION_AFTER_CLOSE_PATH_VERSION')
  text = expected.decode('utf-8', 'strict')
  tree = ast.parse(text, filename=str(target)) if source_form == 'INSTALLATION_PYTHON' else None
  nodes = sum(1 for value in ast.walk(tree)) if tree is not None else 0
  _preflight_require_v1(nodes <= source_node_limit,
   'ORDINARY_PYTEST_INSTALLATION_LITERAL_AST_ALLOWANCE')
  observed.update(text=text, nodes=nodes, complete=True)
  observed['original'] = (observed, scope, installation, install, row, target, version,
   expected, text, nodes, observed['raw_bytes'])
  observed['capture_original'] = (observed, record, scope, capturer, capturer.__code__,
   cache, observed['original'])
  cache[(suffix, source_form)] = (tree, observed)
  record['raw_bytes'] += observed['raw_bytes']
  record['nodes'] += nodes
  _preflight_require_v1(record['raw_bytes'] <= record['source_byte_limit']
   and record['nodes'] <= record['source_node_limit'],
   'ORDINARY_PYTEST_GRAPH_CUMULATIVE_SOURCE_AND_AST_ALLOWANCE')
 except BaseException as error:
  observed['error'] = error
  for owner_errors in (record['errors'], installation['errors'], scope._ordinary_factory_errors_v1):
   if all(error is not prior for prior in owner_errors): owner_errors.append(error)
  raise
 return tree, observed


