    def _ordinary_namespace_mapping_v1(self, root_binding, relative, observed):
     original = self._ordinary_port_context_v1(self._ordinary_candidate_v1)
     if relative == '':
      _preflight_require_v1(any(root_binding is value for value in original['roots'])
       and (observed.st_dev, observed.st_ino) == root_binding['root_identity']
       and self._ordinary_directory_version_v1(observed) == root_binding['root_version'],
       'ORDINARY_NAMESPACE_ACTUAL_HELD_ROOT')
      return root_binding
     _preflight_require_v1(any(root_binding is value for value in original['roots'])
      and type(relative) is str and '\0' not in relative
      and relative == '/'.join(relative.split('/'))
      and all(value not in ('', '.', '..') for value in relative.split('/')),
      'ORDINARY_NAMESPACE_ORIGINAL_RELATIVE_OPERAND')
     current_device = observed.st_dev
     if current_device == root_binding['root_identity'][0]:
      _preflight_require_v1(current_device == self._ordinary_image_v1['filesystem']['root_identity'][0]
       and root_binding['mount_id'] == self._ordinary_image_v1['mount_record']['id'],
       'ORDINARY_NAMESPACE_VIEW_DEVICE_ASSOCIATION')
      self._ordinary_effect_namespace_principal_v1(root_binding, relative, observed)
      return root_binding
     matches = [record for record in self._ordinary_namespace_projections_v1
      if record['view_root'] is root_binding and
      (relative == record['relative'] or relative.startswith(record['relative'] + '/'))]
     _preflight_require_v1(len(matches) == 1, 'ORDINARY_NAMESPACE_UNSELECTED_FOREIGN_DEVICE')
     record = matches[0]
     _preflight_require_v1(record['kind'] in ('GIT_DIRECTORY', 'GIT_POINTER', 'INDEX')
      and record['readonly_mount']['fs'] == record['source_mount']['fs']
      and 'ro' in record['readonly_mount']['options']
      and record['original_source_slot']['owner'] == self._ordinary_storage_owner_v1
      and not record['original_source_slot']['close_attempted']
      and record['original_source_identity'][0] == current_device,
      'ORDINARY_NAMESPACE_ORIGINAL_PROJECTION')
     tail = relative[len(record['relative']):].lstrip('/')
     if record['kind'] != 'GIT_DIRECTORY':
      _preflight_require_v1(not tail and
       (observed.st_dev, observed.st_ino) == record['original_source_identity'],
       'ORDINARY_NAMESPACE_EXACT_PROJECTED_LEAF')
      return record
     source_fd = record['original_source_slot']['returned_fd']
     transient = []
     errors = []
     try:
      parts = tail.split('/') if tail else []
      _preflight_require_v1(len(parts) <= 64, 'ORDINARY_NAMESPACE_PROJECTED_DEPTH')
      for index, component in enumerate(parts):
       final = index == len(parts) - 1
       flags = os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC | (
        os.O_DIRECTORY if not final or stat.S_ISDIR(observed.st_mode) else 0)
       slot = self._ordinary_port_slot_v1(record['source_path'].joinpath(*parts[:index + 1]),
        'ORDINARY_PROJECTED_SOURCE_DIRECTORY' if flags & os.O_DIRECTORY else 'ORDINARY_PROJECTED_SOURCE_FILE')
       transient.append(slot)
       source_fd = self._ordinary_port_open_v1(slot, component, source_fd, flags)
       source_info = self._ordinary_port_call_v1(os.fstat, source_fd)
       _preflight_require_v1(source_info.st_dev == current_device,
        'ORDINARY_NAMESPACE_UNDECLARED_NESTED_PROJECTION')
      source_info = self._ordinary_port_call_v1(os.fstat, source_fd)
      _preflight_require_v1((source_info.st_dev, source_info.st_ino,
       stat.S_IFMT(source_info.st_mode), stat.S_IMODE(source_info.st_mode), source_info.st_uid,
       source_info.st_gid) == (observed.st_dev, observed.st_ino,
       stat.S_IFMT(observed.st_mode), stat.S_IMODE(observed.st_mode), observed.st_uid,
       observed.st_gid), 'ORDINARY_NAMESPACE_PROJECTED_ORIGINAL_OBJECT')
      expected = record['source_records'].get(tail)
      _preflight_require_v1(expected is not None
       and expected['identity'] == (source_info.st_dev, source_info.st_ino)
       and expected['kind'] == ('DIRECTORY' if stat.S_ISDIR(source_info.st_mode) else 'FILE')
       and expected['descriptor_version'] == record['original_source'].census._version(source_info),
       'ORDINARY_NAMESPACE_COMPLETE_ORIGINAL_GIT_GENERATION')
     except BaseException as error: errors.append(error)
     for slot in reversed(transient):
      try: self._ordinary_port_close_v1(slot)
      except BaseException as error: errors.append(error)
     if errors:
      self._ordinary_storage_errors_v1.extend(errors)
     _scan_raise_errors(errors)
     return record


    def _ordinary_resolve_git_v1(self, git_environment):
     self._ordinary_host_check_v1()
     _preflight_require_v1(not getattr(self, '_ordinary_git_attempted_v1', False)
      and type(git_environment) is dict and all(type(k) is str and type(v) is str
       and k.startswith('GIT_') for k, v in git_environment.items()),
      'ORDINARY_GIT_ORIGINAL_BINDING_ATTEMPT')
     self._ordinary_git_attempted_v1 = True
     self._ordinary_git_queries_v1 = []
     self._ordinary_git_bindings_v1 = None
     self._ordinary_git_resolution_v1 = None
     selected = (('git_dir', ('--git-dir',)), ('common_dir', ('--git-common-dir',)),
      ('index', ('--git-path', 'index')))
     outputs = {}
     for kind, suffix in selected:
      argv = ('/usr/bin/git', '--no-optional-locks', 'rev-parse',
       '--path-format=absolute', *suffix)
      effective = self._ordinary_effective_query_argv_v1(argv)
      record = dict(kind=kind, argv=argv, effective_argv=effective, cwd=self.repository,
       environment=git_environment, receipt=None, returned=None, error=None)
      self._ordinary_git_queries_v1.append(record)
      self._ordinary_git_resolution_v1 = record
      try:
       value = self.query.command(effective, cwd=Path(self.repository), git_environment=git_environment)
       record['returned'] = value
       _preflight_require_v1(type(value) is bytes and 1 < len(value) <= 4097
        and value.endswith(b'\n') and b'\n' not in value[:-1]
        and b'\r' not in value and b'\0' not in value,
        'ORDINARY_GIT_EXACT_NATIVE_PATH_OUTPUT')
       spelling = value[:-1].decode('utf-8', 'strict')
       outputs[kind] = Path(_linux_preflight_path_v1(spelling))
      except BaseException as error:
       record['error'] = error
       self._ordinary_factory_errors_v1.append(error)
       raise
      finally:
       try: record['receipt'] = self.query.command_receipt_for_argv_v1(effective)
       except BaseException as error:
        self._ordinary_factory_errors_v1.append(error)
        if record['error'] is not None: _scan_raise_errors([record['error'], error])
        raise
       finally: self._ordinary_git_resolution_v1 = None
     source = self._ordinary_host_original_v1[0]
     lexical = Path(self.repository) / '.git'
     row = source.row_index.get(str(lexical))
     _preflight_require_v1(row is not None and row['kind'] in ('directory', 'file'),
      'ORDINARY_GIT_ORIGINAL_LEXICAL_ADMINISTRATION')
     for kind, path in outputs.items():
      expected = source.row_index.get(str(path))
      _preflight_require_v1(expected is not None
       and expected['kind'] == ('file' if kind == 'index' else 'directory'),
       'ORDINARY_GIT_UNPROTECTED_EXTERNAL_OPERAND:' + kind)
     bindings = dict(lexical_path=lexical, lexical_row=row,
      git_dir=outputs['git_dir'], common_dir=outputs['common_dir'], index=outputs['index'],
      original_source=source, original_queries=self._ordinary_git_queries_v1,
      projections=[], original_projections=None, pointer=None)
     self._ordinary_git_bindings_v1 = bindings
     if row['kind'] == 'directory':
      _preflight_require_v1(outputs['git_dir'] == outputs['common_dir'] == lexical,
       'ORDINARY_GIT_DIRECTORY_SEMANTIC_IDENTITY')
     else:
      slot = self._ordinary_factory_slot_v1(lexical, 'ORDINARY_GIT_POINTER')
      errors = []
      try:
       descriptor = self._ordinary_factory_open_v1(slot, '.git',
        os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC,
        parent_fd=source.anchors[-1][0])
       self._ordinary_host_row_v1(row, descriptor, source.anchors[-1][0], '.git')
       _preflight_require_v1(row['logical_bytes'] <= 4096, 'ORDINARY_GIT_POINTER_BOUND')
       raw = bytearray()
       while len(raw) < row['logical_bytes']:
        part = self._ordinary_transfer_read_v1(descriptor, min(65536, row['logical_bytes'] - len(raw)))
        _preflight_require_v1(part, 'ORDINARY_GIT_POINTER_TRUNCATED')
        raw.extend(part)
       _preflight_require_v1(self._ordinary_transfer_read_v1(descriptor, 1) == b''
        and raw.startswith(b'gitdir: ') and raw.endswith(b'\n')
        and b'\n' not in raw[:-1], 'ORDINARY_GIT_POINTER_GRAMMAR')
       operand = bytes(raw[8:-1]).decode('utf-8', 'strict')
       pointed = Path(os.path.normpath(operand if Path(operand).is_absolute()
        else str(Path(self.repository) / operand)))
       _preflight_require_v1(pointed == outputs['git_dir'],
        'ORDINARY_GIT_POINTER_SEMANTIC_PATH')
       bindings['pointer'] = bytes(raw)
      except BaseException as error: errors.append(error)
      try: self._ordinary_factory_close_v1(slot, settling=True)
      except BaseException as error: errors.append(error)
      if errors: self._ordinary_factory_errors_v1.extend(errors)
      _scan_raise_errors(errors)
     records, originals = {}, {}
     prefix = str(bindings['lexical_path']) + '/'
     for selected in source.rows:
      if selected is bindings['lexical_row'] or selected['path'].startswith(prefix):
       tail = selected['path'][len(str(bindings['lexical_path'])):].lstrip('/')
       version = source.post[selected['path']]
       kind = 'FILE' if selected['kind'] == 'file' else 'DIRECTORY'
       operand = dict(source_row=selected, identity=tuple(version[:2]),
        kind=kind, descriptor_version=version)
       records[tail] = operand
       originals[tail] = (operand, selected, version, version[3], kind)
     bindings['source_records'] = records
     bindings['source_record_originals'] = originals
     bindings['source_records_original'] = (bindings, source,
      bindings['lexical_row'], records, originals)
     return bindings

