    def fail(self, detail):
     if self.query.failure is None:
      error = ValidationReliabilityError('ENGVR_PREPUBLICATION_CUSTODY_FAILED', str(detail))
      if isinstance(detail, BaseException):
       error.__cause__ = detail
       for name in ('owned_process', 'command_process', 'command_receipt'):
        if hasattr(detail, name): setattr(error, name, getattr(detail, name))
      self.query.failure = error
      self._ordinary_storage_errors_v1.append(error)
     raise self.query.failure

