    def _ordinary_dispose_filesystem_v1(self, image):
     self._ordinary_factory_check_v1(settling=True)
     _preflight_require_v1(any(image is row for row in self._ordinary_image_records_v1)
      and image['original_scope'] is self and not image['dispose_attempted']
      and self._ordinary_active_image_v1 is None, 'ORDINARY_SINGLE_ORIGINAL_IMAGE_DISPOSAL')
     self._ordinary_processes_settled_v1()
     _preflight_require_v1(self.query.command_resources_settled_v1(),
      'ORDINARY_ADMINISTRATIVE_CUSTODY_BEFORE_IMAGE_DISPOSAL')
     image['dispose_attempted'] = True
     self._ordinary_active_image_v1 = image
     errors = image['errors']
     if image['mount_slot'] is not None and not _mapper_slot_settled_v1(image['mount_slot']):
      try: self._ordinary_factory_close_v1(image['mount_slot'], settling=True)
      except BaseException as error: errors.append(error)
     if not errors and image['mounted']:
      try:
       self._ordinary_factory_command_v1(('/usr/bin/umount', '--', str(image['mount_path'])), settling=True)
       mounts = _linux_preflight_mounts_v1(self.query.read('/proc/self/mountinfo', settling=True))
       _preflight_require_v1(not any(row['path'] == str(image['mount_path']) for row in mounts),
        'ORDINARY_NATIVE_IMAGE_UNMOUNT_READBACK')
       image['mounted'] = False
      except BaseException as error: errors.append(error)
     if not errors:
      for field in ('loop_slot', 'loop_control_slot', 'slot'):
       slot = image[field]
       if slot is not None and not _mapper_slot_settled_v1(slot):
        try: self._ordinary_factory_close_v1(slot, settling=True)
        except BaseException as error: errors.append(error)
     if not errors:
      observer = self._ordinary_factory_slot_v1(image['loop_device'], 'ORDINARY_LOOP_DISPOSAL_OBSERVER', settling=True)
      try:
       descriptor = self._ordinary_factory_open_v1(observer, image['loop_device'],
        os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC, settling=True)
       try:
        self._ordinary_factory_ioctl_v1(descriptor, 0x4C05, bytes(232), read_extent=232, settling=True)
       except OSError as error:
        _preflight_require_v1(error.errno == errno.ENXIO, 'ORDINARY_NATIVE_LOOP_NOT_DETACHED')
       else:
        raise ValueError('ORDINARY_NATIVE_LOOP_ASSOCIATION_STILL_PRESENT')
      except BaseException as error: errors.append(error)
      try: self._ordinary_factory_close_v1(observer, settling=True)
      except BaseException as error: errors.append(error)
     if not errors:
      self._ordinary_factory_call_v1(os.unlink, image['path'].name,
       dir_fd=image['parent_slot']['returned_fd'], settling=True)
      self._ordinary_factory_call_v1(os.rmdir, image['mount_path'].name,
       dir_fd=image['parent_slot']['returned_fd'], settling=True)
      image['disposed'] = True
      self._ordinary_active_image_v1 = None
     else:
      self._ordinary_factory_errors_v1.extend(errors)
     _scan_raise_errors(errors)

