    def _ordinary_policy_file_v1(self, parent_fd, parent_path, basename, expected):
     _preflight_require_v1(type(expected) is bytes and len(expected) <= 1048576
      and type(basename) is str and '/' not in basename and basename not in ('', '.', '..'),
      'ORDINARY_POLICY_LITERAL_BOUNDED_FILE')
     path = parent_path / basename
     record = dict(path=path, expected=expected, writer=None, reader=None,
      write_complete=False, readback_complete=False, sealed=False, version=None,
      native_flags=None, errors=[])
     self._ordinary_fixed_files_v1.append(record)
     _preflight_require_v1(len(self._ordinary_fixed_files_v1) <= 16,
      'ORDINARY_FINITE_SOURCE_FIXED_CONTROL_FILES')
     if getattr(self, '_ordinary_policy_v1', None) is not None:
      self._ordinary_policy_v1['files'].append(record)
     errors = record['errors']
     try:
      writer = self._ordinary_factory_slot_v1(path, 'ORDINARY_POLICY_WRITER')
      record['writer'] = writer
      fd = self._ordinary_factory_open_v1(writer, basename,
       os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | os.O_CLOEXEC,
       parent_fd=parent_fd)
      for position in range(0, len(expected), 65536):
       self._ordinary_transfer_write_v1(fd, expected[position:position + 65536])
      self._ordinary_factory_call_v1(os.fsync, fd)
      written = self._ordinary_factory_call_v1(os.fstat, fd)
      _preflight_require_v1(stat.S_ISREG(written.st_mode) and written.st_nlink == 1
       and written.st_size == len(expected), 'ORDINARY_POLICY_EXACT_WRITE')
      record['write_complete'] = True
      self._ordinary_factory_close_v1(writer)
      reader = self._ordinary_factory_slot_v1(path, 'ORDINARY_POLICY_READER')
      record['reader'] = reader
      fd = self._ordinary_factory_open_v1(reader, basename,
       os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC, parent_fd=parent_fd)
      reopened = self._ordinary_factory_call_v1(os.fstat, fd)
      _preflight_require_v1(_scan_same_api_version(reopened) == _scan_same_api_version(written),
       'ORDINARY_POLICY_REOPENED_ORIGINAL')
      offset = 0
      while offset < len(expected):
       raw = self._ordinary_transfer_read_v1(fd, min(65536, len(expected) - offset))
       _preflight_require_v1(raw and raw == expected[offset:offset + len(raw)],
        'ORDINARY_POLICY_COMPLETE_BYTE_READBACK')
       offset += len(raw)
      _preflight_require_v1(self._ordinary_transfer_read_v1(fd, 1) == b'', 'ORDINARY_POLICY_SUFFIX')
      record['readback_complete'] = True
      native = self._ordinary_native_v1
      flags = native.flags(fd)
      self._ordinary_factory_debit_v1('native_control_read', 4)
      _preflight_require_v1(not flags & 16, 'ORDINARY_POLICY_PRIOR_SEAL')
      self._ordinary_factory_debit_v1('native_control_write', 4)
      native.flags(fd, flags | 16)
      returned = native.flags(fd)
      self._ordinary_factory_debit_v1('native_control_read', 4)
      after = self._ordinary_factory_call_v1(os.fstat, fd)
      named = self._ordinary_factory_call_v1(os.stat, basename, dir_fd=parent_fd, follow_symlinks=False)
      _preflight_require_v1(returned == flags | 16 and _same_observed_file(after, named),
       'ORDINARY_POLICY_ACTUAL_NATIVE_SEAL')
      record['version'] = _scan_same_api_version(after)
      record['native_flags'] = flags
      record['sealed'] = True
     except BaseException as error:
      errors.append(error)
     for slot in (record['reader'], record['writer']):
      if slot is not None and not _mapper_slot_settled_v1(slot):
       try: self._ordinary_factory_close_v1(slot, settling=True)
       except BaseException as error: errors.append(error)
     if errors: self._ordinary_factory_errors_v1.extend(errors)
     _scan_raise_errors(errors)
     return record

    def _ordinary_policy_features_v1(self):
     root = Path('/sys/kernel/security/apparmor/features')
     slot = self._ordinary_factory_slot_v1(root, 'ORDINARY_APPARMOR_FEATURE_ROOT')
     errors, rows, body = [], [], bytearray()
     try:
      fd = self._ordinary_factory_open_v1(slot, root,
       os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
      def visit(descriptor, relative, depth):
       _preflight_require_v1(depth <= 16 and len(rows) < 4096,
        'ORDINARY_APPARMOR_FEATURE_TREE_BOUND')
       iterator = self._ordinary_factory_iterator_v1(descriptor)
       members = []
       local_errors = []
       try:
        while True:
         try: entry = self._ordinary_factory_call_v1(next, iterator['iterator'])
         except StopIteration: break
         _preflight_require_v1(re.fullmatch(r'[A-Za-z0-9_.-]+', entry.name)
          and len(members) < 4096, 'ORDINARY_APPARMOR_FEATURE_NAME')
         members.append(entry.name)
       except BaseException as error: local_errors.append(error)
       self._ordinary_factory_iterator_close_v1(iterator, local_errors)
       _scan_raise_errors(local_errors)
       _preflight_require_v1(len(set(members)) == len(members), 'ORDINARY_APPARMOR_FEATURE_DUPLICATE')
       for name in sorted(members):
        before = self._ordinary_factory_call_v1(os.stat, name,
         dir_fd=descriptor, follow_symlinks=False)
        directory = stat.S_ISDIR(before.st_mode)
        _preflight_require_v1(directory or stat.S_ISREG(before.st_mode), 'ORDINARY_APPARMOR_FEATURE_KIND')
        child = self._ordinary_factory_slot_v1(root / relative / name, 'ORDINARY_APPARMOR_FEATURE')
        local_errors = []
        try:
         opened = self._ordinary_factory_open_v1(child, name, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC
          | (os.O_DIRECTORY if directory else 0), parent_fd=descriptor)
         info = self._ordinary_factory_call_v1(os.fstat, opened)
         _preflight_require_v1(_same_observed_file(info, before), 'ORDINARY_APPARMOR_FEATURE_ASSOCIATION')
         body.extend((' ' * depth + name + ' {\n').encode('ascii'))
         if directory:
          visit(opened, relative / name, depth + 1)
         else:
          value = bytearray()
          while True:
           raw = self._ordinary_factory_call_v1(os.read, opened, min(65536, 65537 - len(value)))
           _preflight_require_v1(type(raw) is bytes, 'ORDINARY_APPARMOR_FEATURE_RETURN')
           self._ordinary_factory_debit_v1('native_control_read', len(raw))
           _preflight_require_v1(len(value) + len(raw) <= 65536, 'ORDINARY_APPARMOR_FEATURE_EXTENT')
           if not raw: break
           value.extend(raw)
          _preflight_require_v1(re.fullmatch(rb'[A-Za-z0-9_./, +:\t\n-]*', bytes(value)),
           'ORDINARY_APPARMOR_FEATURE_GRAMMAR')
          body.extend(value)
          if value and not value.endswith(b'\n'): body.extend(b'\n')
         body.extend((' ' * depth + '}\n').encode('ascii'))
         after = self._ordinary_factory_call_v1(os.fstat, opened)
         named = self._ordinary_factory_call_v1(os.stat, name, dir_fd=descriptor, follow_symlinks=False)
         _preflight_require_v1(_scan_same_api_version(info) == _scan_same_api_version(after)
          and _scan_same_api_version(before) == _scan_same_api_version(named),
          'ORDINARY_APPARMOR_FEATURE_CHANGED')
         rows.append((str(relative / name), _scan_same_api_version(info)))
         _preflight_require_v1(len(body) <= 1048576, 'ORDINARY_APPARMOR_FEATURE_TOTAL')
        except BaseException as error: local_errors.append(error)
        try: self._ordinary_factory_close_v1(child, settling=True)
        except BaseException as error: local_errors.append(error)
        _scan_raise_errors(local_errors)
      visit(fd, Path('.'), 0)
     except BaseException as error: errors.append(error)
     try: self._ordinary_factory_close_v1(slot, settling=True)
     except BaseException as error: errors.append(error)
     _scan_raise_errors(errors)
     _preflight_require_v1(any(path == 'file' for path, version in rows)
      and any(path.startswith('policy/') for path, version in rows), 'ORDINARY_REQUIRED_KERNEL_MEDIATION')
     return bytes(body), tuple(rows)

    def _ordinary_query_stream_v1(self, query, record, name, limit, *, settling=False):
     _preflight_require_v1(query is self.query and name in ('stdout', 'stderr')
      and record is query._command_call_record is query._last_command_supervision
      and query._command_record_settled_v1(record),
      'ORDINARY_QUERY_ACTUAL_TERMINAL_STREAM_ASSOCIATION')
     root, parent, parent_fd, parent_identity = record['evidence_binding']
     _preflight_require_v1(root == record['evidence_root']
      and parent['slot']['returned_fd'] == parent_fd
      and parent['identity'] == parent_identity
      and not parent['slot']['close_attempted'] and not parent['errors'],
      'ORDINARY_QUERY_ORIGINAL_STREAM_PARENT')
     record['stream_pending'] = True
     slot = dict(path=root / ('command-' + str(record['command_index']) + '.' + name + '.bin'),
      raw=bytearray(), returned_bytes=0, fd=None, raw_owner=None, error=None,
      close_attempted=False, closed=False, complete=False, errors=[], native_slot=None)
     record['streams'][name] = slot
     errors = slot['errors']
     try:
      expected = getattr(record['receipt'], name + '_byte_count')
      _preflight_require_v1(type(expected) is int and 0 <= expected <= limit,
       'LINUX_PREFLIGHT_ADMINISTRATIVE_STREAM_EXTENT')
      root_info = self._ordinary_factory_call_v1(os.fstat, parent_fd, settling=settling)
      named_root = self._ordinary_factory_call_v1(os.lstat, root, settling=settling)
      _preflight_require_v1(stat.S_ISDIR(root_info.st_mode)
       and _same_observed_file(root_info, named_root)
       and (root_info.st_dev, root_info.st_ino) == parent_identity,
       'ORDINARY_QUERY_STREAM_ORIGINAL_ROOT')
      before = self._ordinary_factory_call_v1(os.stat, slot['path'].name,
       dir_fd=parent_fd, follow_symlinks=False, settling=settling)
      before_version = _scan_same_api_version(before)
      _preflight_require_v1(stat.S_ISREG(before.st_mode) and not _stat_is_reparse_point(before)
       and before.st_nlink == 1 and before.st_size == expected,
       'LINUX_PREFLIGHT_ADMINISTRATIVE_STREAM_EXTENT')
      native_slot = slot['native_slot'] = self._ordinary_factory_slot_v1(slot['path'],
       'ORDINARY_QUERY_STREAM', settling=settling)
      slot['fd'] = self._ordinary_factory_open_v1(native_slot, slot['path'].name,
       os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC | os.O_NONBLOCK,
       parent_fd=parent_fd, settling=settling)
      opened = self._ordinary_factory_call_v1(os.fstat, slot['fd'], settling=settling)
      opened_version = _scan_same_api_version(opened)
      named = self._ordinary_factory_call_v1(os.stat, slot['path'].name,
       dir_fd=parent_fd, follow_symlinks=False, settling=settling)
      _preflight_require_v1(_same_observed_file(before, opened)
       and _scan_same_api_version(named) == before_version,
       'LINUX_PREFLIGHT_ADMINISTRATIVE_STREAM_IDENTITY')
      while True:
       query.check(settling=settling)
       requested = min(65536, expected - len(slot['raw']) + 1)
       block = self._ordinary_factory_call_v1(os.read, slot['fd'], requested, settling=settling)
       _preflight_require_v1(type(block) is bytes,
        'LINUX_PREFLIGHT_ADMINISTRATIVE_STREAM_READ')
       slot['returned_bytes'] += len(block)
       slot['raw'].extend(block[:max(0, expected + 1 - len(slot['raw']))])
       query.retained += len(block)
       self._ordinary_factory_debit_v1('raw_read', len(block), settling=settling)
       _preflight_require_v1(len(block) <= requested and slot['returned_bytes'] <= expected
        and query.remaining_output() >= 0 and query.retained <= query.retained_limit,
        'LINUX_PREFLIGHT_ADMINISTRATIVE_STREAM_OUTPUT')
       if not block:
        break
      after = self._ordinary_factory_call_v1(os.fstat, slot['fd'], settling=settling)
      named = self._ordinary_factory_call_v1(os.stat, slot['path'].name,
       dir_fd=parent_fd, follow_symlinks=False, settling=settling)
      _preflight_require_v1(len(slot['raw']) == expected
       and _scan_same_api_version(after) == opened_version
       and _scan_same_api_version(named) == before_version,
       'LINUX_PREFLIGHT_ADMINISTRATIVE_STREAM_CHANGED')
     except BaseException as error:
      errors.append(error)
      if slot['native_slot'] is not None:
       _mapper_slot_open_error_v1(slot['native_slot'], error)
     finally:
      native_slot = slot['native_slot']
      if native_slot is not None:
       try:
        self._ordinary_factory_close_v1(native_slot, settling=True)
       except BaseException as error:
        errors.append(error)
       slot['close_attempted'] = native_slot['close_attempted']
       slot['closed'] = native_slot['closed']
     _scan_raise_errors(errors)
     named = self._ordinary_factory_call_v1(os.stat, slot['path'].name,
      dir_fd=parent_fd, follow_symlinks=False, settling=settling)
     _preflight_require_v1(_scan_same_api_version(named) == before_version,
      'LINUX_PREFLIGHT_ADMINISTRATIVE_STREAM_CHANGED_AFTER_CLOSE')
     slot['raw'] = bytes(slot['raw'])
     slot['complete'] = True
     record['stream_pending'] = False
     return slot['raw']

