    @contextmanager
    def _ordinary_query_binding_progress_v1(self, candidate):
     pool = self._ordinary_query_pool_checked_v1()
     if pool is None or pool['refinement'] is None:
      yield None
      return
     _preflight_require_v1(candidate is self._ordinary_candidate_v1
      and candidate.plan is pool['refinement'][3]
      and getattr(self.query, '_ordinary_query_binding_progress_v1', None) is None,
      'ORDINARY_QUERY_ORIGINAL_C_BINDING_PROGRESS')
     value = (pool, candidate, len(self.query._ordinary_reads_v1), pool['progress'])
     self.query._ordinary_query_binding_progress_v1 = value
     errors, completed = [], False
     try:
      yield value
      completed = True
     except BaseException as error:
      errors.append(error)
     try:
      _preflight_require_v1(self.query._ordinary_query_binding_progress_v1 is value,
       'ORDINARY_QUERY_BINDING_CONTEXT_NOT_REPLACED')
      self.query._ordinary_query_binding_progress_v1 = None
      if completed:
       records = self.query._ordinary_reads_v1[value[2]:]
       _preflight_require_v1(len(records) == pool['demand']['binding_reads']
        and all(row.get('query_pool_completion') is not None
         and row['query_pool_completion'][0] is pool
         and row['query_pool_completion'][5] is value
         and row['complete'] and row['recorded'] and not row['errors']
         and _mapper_slot_settled_v1(row['slot']) for row in records),
        'ORDINARY_QUERY_FULL_CURRENT_BINDING_NOT_PARTIAL_READ_CREDIT')
       before = pool['progress']
       after = (before[0], before[1], before[2] + 1)
       _preflight_require_v1(after[2] <= pool['demand']['bindings'],
        'ORDINARY_QUERY_SOURCE_BINDING_MULTIPLICITY')
       pool['progress'] = self._ordinary_original_query_progress_v1 = after
     except BaseException as error:
      errors.append(error)
     for error in errors:
      if not any(error is old for old in pool['errors']): pool['errors'].append(error)
      if self.query.failure is None: self.query.failure=error
     _scan_raise_errors(errors)

    @contextmanager
    def _ordinary_optional_observation_v1(self, record, kind):
     pool = self._ordinary_query_pool_checked_v1()
     if pool is None:
      yield None
      return
     _preflight_require_v1(pool['refinement'] is not None and not pool['errors']
      and record is self._ordinary_occurrence_record_v1(record['entry'])
      and record is self._ordinary_current_occurrence_v1
      and record['dispatch_attempted'] and not record['kill_attempted']
      and kind in ('startup-repeat', 'terminal-repeat')
      and getattr(self.query, '_ordinary_optional_observation_v1', None) is None,
      'ORDINARY_SOURCE_OPTIONAL_QUERY_ENTRY')
     checks, cells, reservation = self._ordinary_query_pool_remaining_v1(pool)
     role, (commands, responses) = self._ordinary_query_pool_role_v1(pool)
     _preflight_require_v1(role == 'HOST' and self.query.attempts + checks + 6 <= pool['limits']['administrative_attempts']
      and 4 * (commands + 1) + responses + cells <= pool['limits']['cells']
      and self.query.remaining_output() >= reservation + 2,
      'ORDINARY_OPTIONAL_QUERY_NO_FUNDED_COMPLETE_SOURCE_SUFFIX')
     value = (self, self.query, record, record['original'], kind,
      (os.getpid(), threading.get_ident()))
     self.query._ordinary_optional_observation_v1 = value
     errors = []
     try:
      yield value
     except BaseException as error:
      errors.append(error)
     try:
      _preflight_require_v1(self.query._ordinary_optional_observation_v1 is value,
       'ORDINARY_OPTIONAL_QUERY_CONTEXT_UNCHANGED')
      self.query._ordinary_optional_observation_v1 = None
     except BaseException as error:
      errors.append(error)
     for error in errors:
      if not any(error is old for old in pool['errors']): pool['errors'].append(error)
      if self.query.failure is None: self.query.failure=error
     _scan_raise_errors(errors)

