    def _ordinary_prefix_bind_parent_v1(self, host, parent, slot):
     self._ordinary_prefix_checked_v1()
     _preflight_require_v1(host is self._ordinary_host_preparation_v1
      and host is self._ordinary_original_host_preparation_v1
      and host['root_parent'] is None and host['root_parent_slot'] is None
      and type(parent) is type(Path('/')) and parent.is_absolute()
      and str(parent) == _linux_preflight_path_v1(str(parent))
      and not parent.is_relative_to(Path(self.repository))
      and any(slot is row for row in self._ordinary_factory_slots_v1)
      and slot['owner'] == self._ordinary_factory_owner_v1
      and slot['path'] == parent and not slot['close_attempted'],
      'ORDINARY_ONE_ACTUAL_PREFIX_PARENT_BINDING')
     record = dict(host=host, path=parent, slot=slot, handle=None, named=None,
      chain=None, complete=False, errors=[])
     self._ordinary_prefix_parent_v1 = self._ordinary_original_prefix_parent_v1 = record
     try:
      record['chain'] = self._ordinary_factory_chain_v1(parent.parent)
      record['handle'] = self._ordinary_factory_call_v1(os.fstat, slot['returned_fd'])
      record['named'] = self._ordinary_factory_call_v1(os.lstat, parent)
      _preflight_require_v1(stat.S_ISDIR(record['handle'].st_mode)
       and _same_observed_file(record['handle'], record['named'])
       and not _stat_is_reparse_point(record['named'])
       and record['handle'].st_uid == 0
       and not stat.S_IMODE(record['handle'].st_mode) & 0o022,
       'ORDINARY_ACTUAL_PREFIX_EXTERNAL_PARENT')
      host['root_parent'], host['root_parent_slot'] = parent, slot
      original = self._ordinary_prefix_accounting_original_v1
      _preflight_require_v1(original[4] is None and original[5] is None,
       'ORDINARY_PREFIX_PARENT_PREDECESSOR_NOT_REPLACED')
      self._ordinary_prefix_accounting_original_v1 = (*original[:4], parent, slot, *original[6:])
      record['complete'] = True
     except BaseException as error:
      record['errors'].append(error)
      self._ordinary_factory_errors_v1.append(error)
      raise
     return record

    def _ordinary_bind_initial_evidence_domain_v1(self, record):
     self._ordinary_prefix_checked_v1()
