      cell = cells[0]
      parent = cell['slot']['returned_fd']
      before = self._ordinary_factory_call_v1(os.fstat, parent)
      _preflight_require_v1((before.st_dev, before.st_ino) == cell['identity']
       and stat.S_ISDIR(before.st_mode) and stat.S_IMODE(before.st_mode) == 0o700,
       'ORDINARY_COMPILE_CACHE_PARENT_BEFORE_CREATE')
      self._ordinary_factory_call_v1(os.mkdir, 'bytecode', 0o700, dir_fd=parent)
      slot = self._ordinary_factory_slot_v1(record['programme']['physical_root'], 'ORDINARY_COMPILE_CACHE_ROOT')
      record['slot'] = slot
      fd = self._ordinary_factory_open_v1(slot, 'bytecode',
       os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC, parent_fd=parent)
