     image = self._ordinary_host_output_image_v1
     _preflight_require_v1(image is not None and image['original_scope'] is self
      and image['mounted'] and not image['disposed'] and image['role'] == 'HOST_OUTPUT',
      'ORDINARY_ACTUAL_INDEPENDENT_HOST_OUTPUT_IMAGE')
     self._ordinary_parent_output_roots_v1 = []
     self._ordinary_original_parent_output_roots_v1 = self._ordinary_parent_output_roots_v1
     self._ordinary_parent_report_cells_v1 = []
     self._ordinary_original_parent_report_cells_v1 = self._ordinary_parent_report_cells_v1
