     required = {'role', 'logical_root', 'target_root_slot', 'source_preimage_root', 'preimage_rows',
      'original_requested_report_paths', 'reserved_new_cell_count', 'reserved_new_bytes', 'reserved_new_inodes'}
     for spec in programme:
      _preflight_require_v1(type(spec) is dict and set(spec) == required
       and type(spec['original_requested_report_paths']) is tuple
       and len(spec['original_requested_report_paths']) == 1
       and all(type(spec[key]) is int and spec[key] > 0 for key in
        ('reserved_new_cell_count', 'reserved_new_bytes', 'reserved_new_inodes')),
       'ORDINARY_CLOSED_HOST_OUTPUT_SOURCE_OPERANDS')
      matches = [row for row in self._ordinary_host_underlays_v1 if row['role'] == spec['role']]
      _preflight_require_v1(len(matches) == 1, 'ORDINARY_ORIGINAL_OUTPUT_UNDERLAY')
      underlay = matches[0]
      _preflight_require_v1(underlay['complete'] and not underlay['errors']
       and spec['logical_root'] is underlay['logical_root']
       and spec['target_root_slot'] is (underlay['target_slot'] or underlay['parent_slot'])
       and spec['source_preimage_root'] is underlay['source_row']
       and spec['preimage_rows'] is underlay['preimage_rows'],
       'ORDINARY_NATIVE_OUTPUT_PREIMAGE_PRODUCT')
      target = spec['original_requested_report_paths'][0]
      _preflight_require_v1(type(target) is type(Path(self.repository)) and target.parent == spec['logical_root']
       and target.name == self._ordinary_phase_v1 + '.json',
       'ORDINARY_ORIGINAL_CLI_REPORT_LEAF')
      root = dict(scope=self, spec=spec, values=tuple(spec.items()), image=image, underlay=underlay,
       path=image['mount_path'] / spec['role'].lower(), slot=None, transfer=None,
       bind_attempted=False, bound=False, remount_attempted=False,
       unmount_attempted=False, unmounted=False, errors=[])
      self._ordinary_parent_output_roots_v1.append(root)
      self._ordinary_factory_call_v1(os.mkdir, root['path'].name, 0o700,
       dir_fd=image['mount_slot']['returned_fd'])
      slot = self._ordinary_factory_slot_v1(root['path'], 'ORDINARY_HOST_OUTPUT_ROOT')
      root['slot'] = slot
      self._ordinary_factory_open_v1(slot, root['path'].name,
       os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC | os.O_NONBLOCK,
       parent_fd=image['mount_slot']['returned_fd'])
      if underlay['source_row'] is not None:
       root['transfer'] = self._ordinary_copy_original_tree_v1(underlay['source_row'], slot,
        root['path'], role='HOST_OUTPUT')
      cell = dict(scope=self, root=root, target=target, original_target=target,
       writer=None, payload=None, original_payload=None, writer_slot=None, reader_slot=None,
       transitions=[], original_transitions=None, write_attempted=False, written=0,
       publication_attempted=False, published=False, errors=[])
      cell['original_transitions'] = cell['transitions']
      self._ordinary_parent_report_cells_v1.append(cell)
     self._ordinary_parent_output_original_v1 = (programme,
      tuple((root, root['spec'], root['underlay'], root['path'], root['slot'])
       for root in self._ordinary_parent_output_roots_v1),
      tuple((cell, cell['root'], cell['target'], cell['errors']) for cell in self._ordinary_parent_report_cells_v1))
     return programme


