    def _ordinary_issue_prefix_v1(self, *, host, source_programme, memory_programme):
        """Acquire the original ordinary prefix on this Scope, before census.

        The compiled programmes supply requested ceilings and selected native
        operations. They do not supply a filesystem, cgroup, profile or an
        accepted child. Every actual acquisition remains in this Scope.
        """
        import ctypes
        import fcntl
        _preflight_require_v1(type(self) is _LinuxPreflightScopeV1
         and sys.platform == 'linux' and os.geteuid() == 0
         and (self.query.pid, self.query.thread) == (os.getpid(), threading.get_ident())
         and host is self._ordinary_host_preparation_v1 is self._ordinary_original_host_preparation_v1
         and host['scope'] is self and not hasattr(self, '_ordinary_issuer_v1'),
         'ORDINARY_ORIGINAL_PREFIX_ISSUER')
        self._ordinary_prefix_checked_v1()
        _preflight_require_v1(source_programme is host['prefix_programme']
         is host['original_prefix_programme'] and source_programme[10]
         is host['ceiling_programme'] and source_programme[11] is host['original_cutoffs'],
         'ORDINARY_ISSUER_ORIGINAL_COMPILED_PREFIX')
        memory = self._ordinary_issuer_memory_programme_v1(memory_programme)
        record = dict(scope=self, host=host, source_programme=source_programme,
         memory_programme=memory, owner=(os.getpid(), threading.get_ident()),
         parent=None, parent_slot=None, mount_path=None, underlay=None,
         mount_attempted=False, mounted=False, mount_slot=None,
         common_attempted=False, common_adopted=False, common=None,
         bootstrap_attempted=False, bootstrap_adopted=False, bootstrap=None,
         queries=[], current_query=None, runner_ports=[], selected_vectors=(),
         profile=None, receiver_exec_attempted=False, receiver_exec_error=None,
         unmount_attempted=False, unmounted=False, complete=False, errors=[])
        record['original'] = (record, self, host, source_programme, memory,
         record['owner'], record['queries'], record['runner_ports'], record['errors'])
        self._ordinary_issuer_v1 = self._ordinary_original_issuer_v1 = record
        parent = Path('/run') / (self.name + 'ordinary')
        record['parent'] = parent
        try:
         acquisition = self._ordinary_bootstrap_runtime_v1['acquisition']
         storage = _ordinary_initial_prefix_adoption_checked_v1(acquisition['native_input'],
          role='PARENT', root=parent, original_cutoffs=host['original_cutoffs'],
          ceiling_programme=host['ceiling_programme'], prefix_programme=source_programme)
         record['early_prefix'] = storage
         parent_slot = record['parent_slot'] = self._ordinary_factory_slot_v1(
          parent, 'ORDINARY_NATIVE_PREFIX_PARENT')
         parent_fd = self._ordinary_factory_open_v1(parent_slot, parent,
          os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
         parent_info = self._ordinary_factory_call_v1(os.fstat, parent_fd)
         parent_named = self._ordinary_factory_call_v1(os.lstat, parent)
         _preflight_require_v1(stat.S_ISDIR(parent_info.st_mode)
          and (parent_info.st_dev, parent_info.st_ino) ==
           (parent_named.st_dev, parent_named.st_ino)
          and (parent_info.st_uid, parent_info.st_gid,
           stat.S_IMODE(parent_info.st_mode)) == (0, 0, 0o700)
          and (parent_info.st_dev, parent_info.st_ino, parent_info.st_mode,
           parent_info.st_uid, parent_info.st_gid) == storage['root_slot']['identity'],
          'ORDINARY_NATIVE_PREFIX_PARENT_IDENTITY')
         self._ordinary_prefix_bind_parent_v1(host, parent, parent_slot)
         mount_path = record['mount_path'] = storage['mount_path']
         record['underlay'] = storage['underlay']
         mount_slot = record['mount_slot'] = self._ordinary_factory_slot_v1(
          mount_path, 'ORDINARY_NATIVE_PREFIX_MOUNT_ROOT')
         mount_fd = self._ordinary_factory_open_v1(mount_slot, 'prefix',
          os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC,
          parent_fd=parent_fd)
         mounted = self._ordinary_native_v1.mount(mount_fd)
         info = self._ordinary_factory_call_v1(os.fstat, mount_fd)
         usage = self._ordinary_factory_call_v1(os.fstatvfs, mount_fd)
         _preflight_require_v1(mounted['magic'] == 0x01021994
          and (info.st_uid, info.st_gid, stat.S_IMODE(info.st_mode)) == (0, 0, 0o700)
          and usage.f_blocks * usage.f_frsize == source_programme[4]
          and 0 < usage.f_files <= source_programme[5]
          and (info.st_dev, info.st_ino) == storage['mount_slot']['identity'][:2],
          'ORDINARY_PREFIX_NATIVE_CAPACITY_AND_SEPARATE_MOUNT')
         # This Scope adopts the actual earlier mount; it did not repeat
         # the original mount syscall or hide retained Query evidence.
         record['mounted'] = True
         prefix = dict(scope=self, mount_path=mount_path, root_slot=mount_slot,
          root_identity=(info.st_dev, info.st_ino), root_version=_preflight_stamp_v1(info),
          native_mount=mounted, statvfs=usage, source_programme=source_programme,
          user_slots=host['prefix_slots'], unmount_attempted=False,
          unmounted=False, handoff=None, errors=host['prefix_errors'])
         prefix['original'] = (prefix, self, mount_path, mount_slot,
          prefix['root_identity'], prefix['root_version'], mounted,
          usage, source_programme, prefix['user_slots'], prefix['errors'])
         host['prefix_tmpfs'] = host['original_prefix_tmpfs'] = prefix
         _ordinary_initial_prefix_handoff_v1(self, host, prefix, storage)
         return record
        except BaseException as error:
         record['errors'].append(error)
         if not any(error is value for value in host['prefix_errors']):
          host['prefix_errors'].append(error)
         raise

