    def _ordinary_prepare_controller_evidence_v1(self, row):
     parent = self._ordinary_continuous_subroot_v1('CONTROL')
     _preflight_require_v1(parent[1] == self.control and row['evidence_root'] == parent[1] / 'controller-evidence',
      'ORDINARY_CONTROLLER_GENUINE_CONTINUOUS_CONTROL')
     roots = self._ordinary_publication_roots_v1
     path = row['evidence_root']
     record = dict(scope=self, role='controller-evidence', path=path,
      chain=None, slot=None, identity=None, mode=None, errors=[])
     roots.append(record)
     try:
      record['chain'] = self._ordinary_factory_chain_v1(path.parent)
      self._ordinary_factory_call_v1(os.mkdir, path.name, 0o700, dir_fd=parent[2]['returned_fd'])
      slot = record['slot'] = self._ordinary_factory_slot_v1(path, 'ORDINARY_CONTROLLER_EVIDENCE_PARENT')
      descriptor = self._ordinary_factory_open_v1(slot, path.name,
       os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC,
       parent_fd=parent[2]['returned_fd'])
      info = self._ordinary_factory_call_v1(os.fstat, descriptor)
      named = self._ordinary_factory_call_v1(os.stat, path.name,
       dir_fd=parent[2]['returned_fd'], follow_symlinks=False)
      _preflight_require_v1(_same_observed_file(info, named) and stat.S_ISDIR(info.st_mode)
       and info.st_uid == os.geteuid() and stat.S_IMODE(info.st_mode) == 0o700,
       'ORDINARY_CONTROLLER_ACTUAL_EVIDENCE_PARENT')
      record['identity'] = (info.st_dev, info.st_ino)
      record['mode'] = (info.st_uid, info.st_gid, stat.S_IMODE(info.st_mode))
      self._ordinary_publication_root_values_v1 += ((record, path, slot,
       record['chain'], record['identity'], record['mode'], record['errors']),)
      row['evidence_parent'] = record
     except BaseException as error:
      record['errors'].append(error); row['errors'].append(error)
      raise

