    def _ordinary_source_data_read_v1(self, source, path, limit, allocation):
     """Same original Source raw owner; fixed buffer only for issued DATA."""
     state = _ordinary_source_data_operand_original_v1(self,
      allocation['component'], allocation)
     expected = allocation['original']
     _preflight_require_v1(any(item is allocation for item in state['allocations'])
      and expected == (allocation, self, source, allocation['component'],
       allocation['row'], allocation['path'], allocation['version'],
       allocation['kind'], allocation['n'], allocation['layout'],
       allocation['deadline_ns'], allocation['read_exposure'],
       allocation['attempt_exposure'], allocation['attempt_start'],
       allocation['byte_start'], allocation['data_byte_limit'])
      and source is state['source'] and str(path) == allocation['path']
      and source.row_index[allocation['path']] is allocation['row']
      and allocation['row']['logical_bytes'] == allocation['n']
      and allocation['row']['role'] == 'repository'
      and allocation['row']['kind'] == 'file'
      and allocation['raw_credit_open']
      and tuple(source.post[allocation['path']]) == allocation['version']
      and type(limit) is int and limit == allocation['data_byte_limit']
      and allocation['n'] <= limit
      and not allocation['raw_attempted'] and allocation['error'] is None,
      'ORDINARY_DATA_RAW_EXACT_ORIGINAL_CONSUMER')
     allocation['raw_attempted'] = True
     allocation['raw_running'] = True
     fd = None
     buffer = None
     result = None
     failures = []
     source.stage = 'setup'
     try:
      source._check()
      path = Path(path)
      _preflight_require_v1(str(path) in source.files
       and source.state in ('READABLE', 'IN_USE'),
       'LINUX_V2_ADMINISTRATION_OPERAND')
      fd = source._open_path(path)
      before = source._meta(os.fstat, fd)
      _preflight_require_v1(before.st_size == allocation['n'] <= limit
       and source.census._version(before) == source.post[str(path)]
       and source.native.flags(fd) == (source.original_flags[str(path)] | 16),
       'LINUX_V2_ADMINISTRATION_IDENTITY')
      self._ordinary_source_data_allocator_projection_v1()
      buffer = bytearray(before.st_size)
      extent = 0
      while True:
       self._ordinary_source_data_allocator_projection_v1()
       _preflight_require_v1(source.read_attempts - allocation['attempt_start']
        < allocation['attempt_exposure'],
        'ORDINARY_DATA_ORIGINAL_READ_ATTEMPT_CREDIT')
       block = source._read(fd, min(65536, before.st_size - extent + 1))
       allocation['actual_read'] = source.read_bytes - allocation['byte_start']
       source.auxiliary_read_bytes += len(block)
       end = extent + len(block)
       _preflight_require_v1(end <= before.st_size,
        'LINUX_V2_ADMINISTRATION_EXTENT')
       if not block:
        break
       buffer[extent:end] = block
       extent = end
      _preflight_require_v1(extent == before.st_size
       and source.census._version(source._meta(os.fstat, fd))
        == source.post[str(path)]
        == source.census._version(source._meta(path.lstat))
       and source.native.flags(fd) == (source.original_flags[str(path)] | 16),
       'LINUX_V2_ADMINISTRATION_CHANGED')
      self._ordinary_source_data_allocator_projection_v1()
      result = bytes(buffer)
      _preflight_require_v1(type(result) is bytes
       and len(result) == allocation['n'],
       'ORDINARY_DATA_RAW_RETURN_EXTENT')
     except BaseException as error:
      failures.append(error)
     finally:
      allocation['actual_read'] = source.read_bytes - allocation['byte_start']
      allocation['actual_read_attempts'] = source.read_attempts - allocation['attempt_start']
      if fd is not None:
       try:
        source._close(fd)
       except BaseException as error:
        failures.append(error)
     allocation['raw_running'] = False
     if failures:
      allocation['error'] = failures[0]
      allocation['errors'] = tuple(failures)
      if source.failure is None:
       source.failure = failures[0]
      if source.phase == 'work':
       source.state = 'FAILED'
      for error in failures:
       if not any(error is prior for prior in self._ordinary_factory_errors_v1):
        self._ordinary_factory_errors_v1.append(error)
      _scan_raise_errors(failures)
     buffer = None
     allocation['raw'] = result
     allocation['raw_complete'] = True
     allocation['raw_credit_open'] = False
     allocation['raw_result_original'] = (allocation, result, allocation['version'],
      allocation['n'], allocation['actual_read'], allocation['actual_read_attempts'])
     return result


