         attempt["reads"].append(selected_read)
         start_before=_ordinary_data_runtime_start_from_raw_v1(stat_before,pid)
         mapping_before=_ordinary_data_runtime_maps_from_raw_v1(maps_before,unique)
         exe_link_before=install._ordinary_call_v1(os.readlink,proc+"/exe")
