         exe_name_before=sys.executable
         public_exe_before=install._ordinary_call_v1(os.stat,exe_name_before)
         _preflight_require_v1(install.census._version(public_exe_before)==exe_row["version"],
          "SOURCE_DATA_SYS_EXECUTABLE_IS_ACTUAL_EXECUTED_FILE")
         lib_row=runtime_roles[1][2]
         lib_mode=runtime_roles[1][1]
         _preflight_require_v1(lib_mode in ("MAPPED_LIBRARY","STATIC_IN_EXECUTABLE")
          and (lib_mode!="STATIC_IN_EXECUTABLE" or lib_row is exe_row),
          "SOURCE_DATA_EXPLICIT_STATIC_OR_MAPPED_PYTHON_OWNER")
         modules=tuple((name,sys.modules.get(name)) for name in
          ("json","json.decoder","json.scanner","_json","_sre"))
