    def _ordinary_source_data_construct_issued_v1(self, allocation, scan, *,
      managed_request):
     state = _ordinary_source_data_operand_original_v1(self,
      allocation['component'], allocation)
     self._ordinary_source_data_raw_binding_check_v1(allocation)
     original_scan = allocation['stages'].get('scan')
     _preflight_require_v1(original_scan is not None
      and original_scan['attempted'] and original_scan['complete']
      and original_scan['error'] is None and original_scan['scan'] is scan
      and original_scan['deadline_ns'] == state['deadline_ns']
      and allocation['error'] is None,
      'ORDINARY_DATA_CONSTRUCTION_ORIGINAL_SCAN')
     _preflight_require_v1(type(scan) is dict
      and scan['raw'] is allocation['raw']
      and scan['parser_programme'] == allocation['parser_programme']
      and type(scan['original']) is tuple and len(scan['original']) == 9
      and scan['original'][8] == allocation['parser_programme'],
      'ORDINARY_DATA_CONSTRUCTION_ORIGINAL_PARSER')
     demand = scan['demand']
     for key in ('decoded_codepoints', 'json_nodes',
        'json_string_codepoints_bound', 'json_number_bytes',
        'json_container_slots', 'json_records'):
      _ordinary_data_nonnegative_v1(demand[key],
       'ORDINARY_DATA_SCANNED_CONSTRUCTION_DEMAND')
     _preflight_require_v1(0 < demand['json_nodes'] <= allocation['data_node_limit'],
      'ORDINARY_DATA_CONSTRUCTION_INDEPENDENT_NODE_ALLOWANCE')
     _preflight_require_v1(type(managed_request) is dict,
      'ORDINARY_DATA_CONSTRUCTION_LAYOUT_UNSUPPORTED')
     _preflight_require_v1(managed_request['payload_byte_request']
      == (demand['maximum_decode_slice_bytes']
       if allocation['parser_programme'] == 'JSONL_TEXTIO_LIST_V1' else 0),
      'ORDINARY_DATA_CONSTRUCTION_BYTE_SLICE_REQUEST')
     managed_demand = sum(_ordinary_data_nonnegative_v1(size,
      'ORDINARY_DATA_CONSTRUCTION_MANAGED_COMPONENT')
      for name, size in managed_request['component_requests'])
     allowance = dict(decoded_codepoint_limit=demand['decoded_codepoints'],
      json_node_limit=demand['json_nodes'],
      json_string_codepoint_limit=demand['json_string_codepoints_bound'],
      json_number_byte_limit=demand['json_number_bytes'],
      json_container_slot_limit=demand['json_container_slots'],
      json_record_limit=demand['json_records'],
      retained_heap_byte_limit=managed_demand,
      deadline_ns=state['deadline_ns'])
     bounds = tuple(allowance.items())
     issued = self._ordinary_source_data_managed_request_issue_v1(allocation,
      stage='construction', bounds=bounds, managed_request=managed_request)
     issued['allowance'] = allowance
     issued['attempted'] = True
     try:
      value = _ordinary_source_data_construct_v1(scan,
       construction_allowance=allowance)
      issued['value'] = value
      issued['complete'] = True
      return value
     except BaseException as error:
      issued['error'] = error
      allocation['error'] = error
      allocation['errors'] = (error,)
      if not any(error is prior for prior in self._ordinary_factory_errors_v1):
       self._ordinary_factory_errors_v1.append(error)
      raise


