def _ordinary_data_runtime_start_from_raw_v1(raw, pid):
 _preflight_require_v1(type(raw) is bytes and type(pid) is int and pid > 0,
  "SOURCE_DATA_ACTUAL_PROCESS_STAT_RAW")
 close = raw.rfind(b") ")
 _preflight_require_v1(raw.startswith(str(pid).encode("ascii")+b" (") and close > 0,
  "SOURCE_DATA_ACTUAL_PROCESS_STAT_PREFIX")
 fields = raw[close+2:].split()
 _preflight_require_v1(len(fields) >= 20 and fields[19].isdigit()
  and len(fields[19]) <= 20, "SOURCE_DATA_ACTUAL_PROCESS_START_FIELD")
 return int(fields[19])


def _ordinary_data_runtime_maps_from_raw_v1(raw, rows):
 _preflight_require_v1(type(raw) is bytes and type(rows) is tuple,
  "SOURCE_DATA_ACTUAL_MAPS_RAW")
 keys = tuple((os.major(row["version"][0]), os.minor(row["version"][0]),
  row["version"][1]) for row in rows)
 selected = [[] for row in rows]
 for line in raw.split(b"\n"):
  if not line:
   continue
  parts = line.split(None,5)
  _preflight_require_v1(len(parts) in (5,6), "SOURCE_DATA_MAPS_LINE_SHAPE")
  addresses = parts[0].split(b"-")
  device = parts[3].split(b":")
  _preflight_require_v1(len(addresses)==2 and len(device)==2
   and all(0 < len(value) <= 16 for value in
    (addresses[0],addresses[1],parts[2],device[0],device[1]))
   and parts[4].isdigit() and len(parts[4]) <= 20
   and len(parts[1])==4
   and parts[1][0:1] in (b"r",b"-")
   and parts[1][1:2] in (b"w",b"-")
   and parts[1][2:3] in (b"x",b"-")
   and parts[1][3:4] in (b"p",b"s"),
   "SOURCE_DATA_MAPS_SUPPORTED_KERNEL_FIELDS")
  start,end = int(addresses[0],16),int(addresses[1],16)
  offset = int(parts[2],16)
  major,minor,inode = int(device[0],16),int(device[1],16),int(parts[4])
  _preflight_require_v1(0 <= start < end < (1 << 64)
   and 0 <= offset < (1 << 64) and 0 <= inode < (1 << 64),
   "SOURCE_DATA_MAPS_ADDRESS_INTERVAL")
  key = (major,minor,inode)
  item = (start,end,parts[1],offset,major,minor,inode)
  for index, expected in enumerate(keys):
   if key == expected:
    selected[index].append(item)
 return tuple(tuple(items) for items in selected)



# NEW private method in the existing _LinuxPreflightScopeV1.
# Called inside the original strong layout caller's already-owned single
# attempt/try block, before its layout collector and before DATA issuance.
# Original caller funds the complete native/control/heap/source work FIRST.


# REVIEWER SOURCE-ONLY PROPOSAL for the existing validation_reliability owner.
# Not applied; no source/native permission, allocator-fit promise, or new module.
# Existing owner globals required: json and time. No QTT import/evaluation here.
#
# Caller prerequisites BEFORE entry: authentic retained immutable raw bytes;
# independently issued scanner metadata/UTF8/work/lifetime allowance; actual
# original native heap/lifetime binding. Raw chunk-list + join coexistence belongs
# to the source getter's separate original reservation. This code does not refund
# failed work, infer heap bytes from JSON size, or establish native enforcement.
#
# Two stages are intentional. lexical_admission constructs no aggregate decoded
# string or JSON values. The original resource owner receives its demand and must
# issue construction_allowance from its independently held remaining pool before
# construct is called. Unsupported heap-sizing/runtime integration must deny at
# that original issuer seam, rather than invent an allocator-per-node multiplier.
# retained_heap_byte_limit below is the issued credit, not proof of allocator
# coverage or successful fit. Native rejection/exhaustion and cutoffs stay active.
#
# Source semantics: ordinary json.loads defaults (duplicates last-wins, NaN and
# +/-Infinity, top-level scalars, escaped lone surrogates, original integer limits).
# Parser programme is source-selected and frozen: JSON_DEFAULT_V1 uses ordinary
# JSON; JSONL_TEXTIO_LIST_V1 preserves Atomic TextIO CR/LF/CRLF and LIST result;
# JSONL_SPLITLINES_TUPLE_V1 preserves getter Unicode str.splitlines and TUPLE.
# Both JSONL programmes use line.strip() only as the blank predicate and parse
# the original untrimmed line. Generic getter aggregate decoded text is retained.
# Admission errors may precede the original parser's syntax/allocation failure;
# exception wording and partial parsing prefix are not claimed identical.
#
# Source associations:
# pr168_gfp_real_computation/io.py:13-23; canonical_rows.py:32-55.
# tools/pr168_rp_report_writer.py:16-38, ordinary header/ordered-shard json.loads.
# Primary semantic references (not installed-runtime identity evidence):
# https://docs.python.org/3.14/library/json.html
# https://github.com/python/cpython/blob/v3.14.6/Lib/json/decoder.py
# https://github.com/python/cpython/blob/v3.14.6/Objects/unicodetype_db.h
#
# scanner exact fields: raw_byte_limit, utf8_codepoint_limit, maximum_depth,
# jsonl_span_limit, lexical_visit_limit, deadline_ns.
# constructor exact fields: decoded_codepoint_limit, json_node_limit,
# json_string_codepoint_limit, json_number_byte_limit, json_container_slot_limit,
# json_record_limit, retained_heap_byte_limit, deadline_ns.


