def _ordinary_source_data_construct_v1(scan, *, construction_allowance):
 if type(scan) is not dict or scan.get("construction_attempted") is not False:
  raise ValueError("SOURCE_DATA_ONE_CONSTRUCTION_ATTEMPT")
 scan["construction_attempted"] = True
 scan["construction_allowance"] = construction_allowance
 fields = ("decoded_codepoint_limit", "json_node_limit", "json_string_codepoint_limit",
  "json_number_byte_limit", "json_container_slot_limit", "json_record_limit",
  "retained_heap_byte_limit", "deadline_ns")
 scan_fields = ("raw_byte_limit", "utf8_codepoint_limit", "maximum_depth",
  "jsonl_span_limit", "lexical_visit_limit", "deadline_ns")
 try:
  original = scan.get("original")
  if (type(original) is not tuple or len(original) != 9 or original[0] is not scan
    or original[1] is not scan.get("raw") or original[2] != scan.get("kind")
    or original[3] is not scan.get("scan_allowance")
    or original[4] is not scan.get("scan_limits")
    or original[5] is not scan.get("spans")
    or original[6] is not scan.get("demand")
    or tuple(original[6].items()) != original[7]
    or original[8] != scan.get('parser_programme')
    or ((original[2] == 'JSON' and original[8] != 'JSON_DEFAULT_V1')
     or (original[2] == 'JSONL' and original[8] not in
      ('JSONL_TEXTIO_LIST_V1', 'JSONL_SPLITLINES_TUPLE_V1')))
    or scan.get("complete") is not True or scan.get("error") is not None):
   raise ValueError("SOURCE_DATA_ORIGINAL_COMPLETE_SCAN")
  if _ordinary_source_data_limits_v1(original[3], scan_fields) != original[4]:
   raise ValueError("SOURCE_DATA_ORIGINAL_SCAN_ALLOWANCE_DRIFT")
  limits = _ordinary_source_data_limits_v1(construction_allowance, fields)
  scan["construction_limits"] = limits
  demand = original[6]
  names = ("decoded_codepoints", "json_nodes", "json_string_codepoints_bound",
   "json_number_bytes", "json_container_slots", "json_records")
  if any(demand[name] > limits[index] for index, name in enumerate(names)):
   raise ValueError("SOURCE_DATA_CONSTRUCTION_LOGICAL_ALLOWANCE")
  if limits[7] > original[4][5]:
   raise ValueError("SOURCE_DATA_CONSTRUCTION_DEADLINE_EXTENSION")
  scan["issued_retained_heap_byte_limit"] = limits[6]

  def checkpoint():
   scan["counts"]["clock_checks"] += 1
   if time.monotonic_ns() >= limits[7]:
    raise ValueError("SOURCE_DATA_CONSTRUCTION_DEADLINE")
   if _ordinary_source_data_limits_v1(construction_allowance, fields) != limits:
    raise ValueError("SOURCE_DATA_CONSTRUCTION_ALLOWANCE_DRIFT")

  checkpoint()
  raw = original[1]
  if original[2] == "JSON":
   text = raw.decode("utf-8", "strict")
   scan["current_text"] = text
   scan['decoded_text'] = text
   checkpoint()
   result = json.loads(text)
   scan["partial_values"] = result
   checkpoint()
  elif original[8] == 'JSONL_SPLITLINES_TUPLE_V1':
   text = raw.decode('utf-8', 'strict')
   scan['current_text'] = text
   scan['decoded_text'] = text
   checkpoint()
   lines = text.splitlines()
   scan['partial_lines'] = lines
   checkpoint()
   values = []
   scan['partial_values'] = values
   for line in lines:
    checkpoint()
    if line.strip():
     value = json.loads(line)
     values.append(value)
     checkpoint()
   result = tuple(values)
   checkpoint()
  else:
   result = []
   scan["partial_values"] = result
   for start, end in original[5]:
    checkpoint()
    line_raw = raw[start:end]
    text = line_raw.decode("utf-8", "strict")
    scan["current_text"] = text
    checkpoint()
    value = json.loads(text)
    result.append(value)
    checkpoint()
    scan["current_text"] = None
    del text, line_raw
  scan["result"] = result
  scan["constructed"] = True
  scan["current_text"] = None
  return result
 except BaseException as error:
  if scan.get("error") is None:
   scan["error"] = error
  raise


