def _ordinary_control_compiled_containers_v1(raw, filename, *, flags, optimize, selected):
 import ast, types
 from tools.validation_scope_registry import _ordinary_control_selected_source_unit_v1
 if (type(filename) is not str or not filename or '\0' in filename
   or type(optimize) is not int or optimize not in (0,1,2)):
  raise ValueError('CONTROL_PARTITION_ORIGINAL_COMPILE_CONTEXT')
 cells = _ordinary_control_source_container_units_v1(raw, selected, flags=flags)
 statements, definitions, ignores = {}, [], None
 for keys, text, interval in cells:
  tree = compile(text, filename, 'exec', flags=flags | ast.PyCF_ONLY_AST,
   dont_inherit=True, optimize=optimize)
  unit, found = _ordinary_control_selected_source_unit_v1(tree, keys)
  current = tuple((item.lineno,item.tag) for item in unit.type_ignores)
  if ignores is None: ignores = unit.type_ignores
  elif current != tuple((item.lineno,item.tag) for item in ignores):
   raise ValueError('CONTROL_PARTITION_WHOLE_TYPE_IGNORE_CONTEXT')
  for node in unit.body:
   position=(node.lineno,node.col_offset,node.end_lineno,node.end_col_offset)
   if position in statements:
    if ast.dump(node,include_attributes=True) != ast.dump(statements[position],include_attributes=True):
     raise ValueError('CONTROL_PARTITION_ORIGINAL_STATEMENT_DISAGREEMENT')
   else: statements[position]=node
  for found_key in found:
   if (found_key[0],found_key[1]) in keys: definitions.append(found_key)
 if len(definitions) != len(selected) or len({(r[0],r[1]) for r in definitions}) != len(selected):
  raise ValueError('CONTROL_PARTITION_ONE_ORIGINAL_DEFINITION')
 unit=ast.Module(body=[statements[p] for p in sorted(statements)],type_ignores=ignores)
 root=compile(unit,filename,'exec',flags=flags,dont_inherit=True,optimize=optimize)
 if type(root) is not types.CodeType: raise ValueError('CONTROL_COMPILED_MODULE')
 codes,pending=[],[root]
 while pending:
  code=pending.pop();codes.append(code)
  pending.extend(c for c in code.co_consts if type(c) is types.CodeType)
 return root,tuple(codes),tuple(sorted(definitions,key=lambda row:row[1]))


def _ordinary_source_absent_operand_v1(scope, record, relative):
 """Observe one missing member of the original immutable Source namespace."""
 _preflight_require_v1(type(scope) is _LinuxPreflightScopeV1 and type(record) is dict
  and record['scope'] is scope and record['source'] is scope.source
  and type(record['source_operands']) is list and type(record['errors']) is list,
  'ORDINARY_ABSENT_ORIGINAL_SOURCE_COMPONENT')
 _mapper_portable_relative_v1(relative)
 source = scope.source
 host = scope._ordinary_host_original_v1
 _preflight_require_v1(type(host) is tuple and len(host) == 7
  and all(value is original for value,original in zip((source,source.rows,source.row_index,
   source.post,source.original_flags,source.originals,source.anchors),host,strict=True))
  and type(source) is _LinuxImmutableSourceSealV2
  and source.state == 'READABLE' and source.failure is None
  and source._ordinary_meter_scope_v1 is scope
  and type(source.census) is _LinuxPreflightCensusV1 and source.census.complete
  and source.pid == scope.query.pid == os.getpid()
  and source.thread == scope.query.thread == threading.get_ident(),
  'ORDINARY_ABSENT_LIVE_ORIGINAL_SOURCE_GENERATION')
 slot = _ordinary_rp_join_slot_v1(scope, relative)
 row, version, suffix = slot['absent_parent'], slot['absent_version'], slot['absent_suffix']
 _preflight_require_v1(slot['source_row'] is None and type(row) is dict
  and source.row_index.get(row['path']) is row
  and any(row is original for original in source.census.records)
  and row['role'] == 'repository' and row['kind'] == 'directory'
  and str(source.root) == str(source.census.roots['repository'])
  and row['path'] in source.directories and tuple(source.post[row['path']]) == version
  and type(suffix) is tuple and suffix and suffix[0] not in row['roster'],
  'ORDINARY_ABSENT_AUTHENTIC_PROTECTED_PARENT')
 errors, opened = [], []
 observed = dict(path=relative, row=row, version=version, source_form='ABSENT',
  raw_bytes=0, text=None, nodes=0, attempted=True, complete=False, error=None,
  source=source, suffix=suffix, no_entry=None, opened=opened, errors=errors,
  owner=(os.getpid(),threading.get_ident()))
 record['source_operands'].append(observed)
 parent_fd = None
 old_stage = source.stage
 source.stage = 'setup'
 try:
  source._check()
  source._anchors_live()
  _preflight_require_v1(source.row_index.get(row['path']) is row
   and tuple(source.post[row['path']]) == version and suffix[0] not in row['roster'],
   'ORDINARY_ABSENT_ORIGINAL_PARENT_NOT_REPLACED')
  for part in Path(row['path']).parts:
   cell = dict(part=part, fd=None, close_attempted=False, closed=False)
   opened.append(cell)
   fd = source._open(part, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC | os.O_DIRECTORY,
    **({} if parent_fd is None else dict(dir_fd=parent_fd)))
   cell['fd'] = fd
   parent_fd = fd
  source._identity(parent_fd, row, 'sealed')
  named = source._meta(os.lstat, row['path'])
  _preflight_require_v1(source.census._version(named) == version,
   'ORDINARY_ABSENT_PARENT_PATH_BEFORE')
  try:
   source._meta(os.stat, suffix[0], dir_fd=parent_fd, follow_symlinks=False)
  except FileNotFoundError as missing:
   observed['no_entry'] = missing
   _preflight_require_v1(missing.errno == 2,
    'ORDINARY_ABSENT_ACTUAL_NATIVE_ENOENT')
  else:
   raise ValueError('ORDINARY_ABSENT_MEMBER_NOW_PRESENT')
  source._identity(parent_fd, row, 'sealed')
  named = source._meta(os.lstat, row['path'])
  _preflight_require_v1(source.census._version(named) == version
   and source.row_index.get(row['path']) is row
   and tuple(source.post[row['path']]) == version and suffix[0] not in row['roster'],
   'ORDINARY_ABSENT_PARENT_PATH_AFTER')
  source._anchors_live()
  source._check()
 except BaseException as error:
  errors.append(error)
 finally:
  for cell in reversed(opened):
   fd = cell['fd']
   if fd is not None:
    try:
     cell['close_attempted'] = True
     source._close(fd)
     cell['closed'] = True
    except BaseException as error:
     errors.append(error)
  source.stage = old_stage
 if not errors:
  try:
   source._check()
   _preflight_require_v1(observed['no_entry'] is not None and opened
    and all(cell['closed'] and cell['fd'] not in source.owned for cell in opened),
    'ORDINARY_ABSENT_ORIGINAL_DESCRIPTOR_SETTLEMENT')
   observed['absence_original'] = (observed,scope,source,row,version,relative,suffix,
    observed['no_entry'],opened,tuple((cell,tuple(cell.items())) for cell in opened),
    observed['owner'],errors)
   observed['complete'] = True
  except BaseException as error:
   errors.append(error)
 if errors:
  observed['error'] = errors[0]
  if source.failure is None: source.failure = errors[0]
  if source.phase == 'work': source.state = 'FAILED'
  escaping = list(errors)
  for error in tuple(errors):
   for owner_errors in (record['errors'], scope._ordinary_factory_errors_v1):
    try:
     if not any(error is old for old in owner_errors): owner_errors.append(error)
    except BaseException as recording_error:
     escaping.append(recording_error)
  _scan_raise_errors(escaping)
 return observed


