 while pending:
  left, right = pending.pop()
  if type(left) is not type(right): return False
  if left is None: continue
  if type(left) in (bool, int, str, bytes):
   if left != right: return False
  elif type(left) is float:
   if not math.isfinite(left) or not math.isfinite(right) or left.hex() != right.hex(): return False
  elif type(left) in (tuple, list):
   if len(left) != len(right): return False
   pending.extend(zip(left, right))  # bounded by authentic Source default shape
  elif type(left) is dict:
   if len(left) != len(right): return False
   for (lk, lv), (rk, rv) in zip(left.items(), right.items()):
    pending.append((lk, rk)); pending.append((lv, rv))
  else: raise ValueError('CONTROL_DEFAULT_LITERAL_TYPE_UNSUPPORTED')
 return True


