  _preflight_require_v1(native_input['native_instance']is native and native_input['native_init_original']is original
   and type(meter)is tuple and len(meter)==5 and meter[0]is native_input and meter[1]is checked
   and meter[2]is checked.__code__ and meter[3]is record and meter[4]is record['prefix_original'],
   'ORDINARY_INITIAL_SAME_PRIVATE_CONSTRUCTOR_METER')
  _ordinary_initial_native_debit_v1(native_input,'INITIAL_NATIVE_CONSTRUCTOR_CALL')
