def _ordinary_control_current_parser_request_v1(layout, raw, profile):
 # This is prospective arithmetic through the original parse request owner,
 # not authentication of a supplied profile. Its caller must bind the same
 # independently selected protected Source, pinned C branch and profile
 # before tokenize/parse can begin. No successful AST/Code issues credit.
 if type(raw) is not bytes or type(profile) is not tuple or len(profile) not in (11, 12):
  raise ValueError('CONTROL_CURRENT_ORIGINAL_SOURCE_PROFILE')
 (tokens, requests, object_slots, helper_bytes, arrays, ast_profile,
  name_count, name_characters, number_count, number_characters,
  valid_first_pass) = profile[:11]
 if (_ordinary_data_size_v1(layout, 'pointer') != 8
   or any(type(v) is not int or v < 0 for v in (tokens, object_slots,
    helper_bytes, arrays, name_count, name_characters,
    number_count, number_characters)) or tokens == 0
   or type(requests) is not tuple or type(valid_first_pass) is not bool):
  raise ValueError('CONTROL_CURRENT_SUPPORTED_SOURCE_AND_LAYOUT')
 # Valid-first-pass is allowed only with the independently proved complete
 # raw grammar/semantic branch, UTF8/cookie, flags/optimize and recursion
 # domain. MemoryError aborts p->error_indicator rather than restarting an
 # invalid-rule pass. Unproved syntax takes both original28/29 passes.
 passes = 28 if valid_first_pass else 57
 memo_count = passes * tokens
 if len(profile) == 12:
  if valid_first_pass is not True or type(profile[11]) is not int or not 0 <= profile[11] <= memo_count:
   raise ValueError('CONTROL_CURRENT_QUALIFIED_SOURCE_MEMO')
  memo_count = profile[11]
 memo_request = (32, memo_count)
 arena = _ordinary_control_parser_arena_request_v1(layout,
  (memo_request,) + requests, 2 * tokens + object_slots + name_count + number_count)
 capacity = 1
 while capacity < tokens:
  capacity *= 2
 # The actual C tokenizer retains one bounded byte operand per token. Its
 # source bytes form one partition; newline/INDENT/ENDMARKER empty operands
 # each retain only their separate original object header.
 token_bytes = tokens * _ordinary_data_size_v1(layout, 'bytes_prefix')
 token_bytes += 2 * len(raw) + 2 * tokens
 # Identifier interning can retain all returned strings but does not create
 # an independent whole-source copy for each identifier. Decimal conversion
 # is separately bounded by the actual original spelling character sum.
 names = (name_count * _ordinary_data_size_v1(layout, 'unicode_prefix')
  + 4 * (name_characters + name_count))
 integer_digits = (4 * number_characters + 29 * number_count) // 30
 numbers = (number_count * (_ordinary_data_size_v1(layout, 'int_prefix')
   + 2 * _ordinary_data_size_v1(layout, 'float'))
  + _ordinary_data_size_v1(layout, 'int_digit_bytes') * integer_digits)
 if number_count:
  numbers += _ordinary_data_dtoa_requests_v1(layout)
 converted = _ordinary_control_python_ast_request_v1(layout, ast_profile)
 rows = (
  ('PARSER_TOKEN_TABLE_AND_ONE_RESIZE', 56 * capacity
   + 8 * (capacity + capacity // 2)),
  ('PARSER_COMPLETE_PARTITIONED_TOKEN_BYTES', token_bytes),
  ('PARSER_ORIGINAL_SHARED_ARENA_AND_MEMO', arena),
  ('PARSER_ORIGINAL_SEMANTIC_HELPER_OBJECTS', helper_bytes),
  ('PARSER_ORIGINAL_GENERATED_LOCAL_ARRAYS', arrays),
  ('PARSER_ORIGINAL_IDENTIFIER_AND_NUMBER_RESULTS', names + numbers),
  *converted,
  ('SOURCE_ONE_ACTIVE_CONTAINER_TEXT',
   _ordinary_data_unicode_request_v1(layout, len(raw))
   + _ordinary_data_bytes_request_v1(layout, len(raw))),
 )
 # AST conversion remains held for the selected compile; the original
 # sequential partition route holds only the current container text and
 # original source lines, never a list of all masked Source text copies.
 retained = tuple(name for name, value in converted)
 return rows, retained
